/* 自编中文译文（非教材官方译文）. English and provenance are preserved. Generated by build-book2-translations.cjs. */
window.BOOK2_TRANSLATIONS={"version":1,"label":"自编中文译文（非教材官方译文）","lessons":[{"lessonId":"nce-b2-eef57c-l001","book":2,"number":1,"title":"A private conversation","paragraphs":[{"index":0,"enSha256":"5ed98f5f8f1fe12feeb5001405926e77ff9c7fb87daf195423f3fe29db9ca46b","zh":"上周我去看戏，座位很好，戏也很有意思，可我却没能好好欣赏。有一男一女两个年轻人坐在我后面，大声地说着话。我非常生气，因为我听不见演员的声音。我转过身，愤怒地看着他们，可他们毫不理会。最后我实在忍不住了，又转过身去，气愤地说：‘我一个字也听不见！’"},{"index":1,"enSha256":"de0a847b5b1602f002d272a3e5b92a747a388cb7216bbe11c79cd8c1121456ab","zh":"‘关你什么事，’那年轻男子无礼地说，‘这是私人谈话！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l002","book":2,"number":2,"title":"Breakfast or lunch?","paragraphs":[{"index":0,"enSha256":"70e3ec8015454df9a7b95554eb2e3831d91989f51dac406fb484496853611b6b","zh":"那天是星期天。我星期天从不早起，有时一直赖在床上，直到吃午饭的时候。上个星期天我起得很晚。我望向窗外，外面一片昏暗。‘这是什么天气啊！’我心想，‘又下雨了。’就在这时，电话响了，是我露西阿姨打来的。‘我刚坐火车到，’她说，‘我这就来看你。’"},{"index":1,"enSha256":"515304afbf6e4762998f1870f371d33495bb94ca09fe5ea423fc940f6124fd17","zh":"‘可我还在吃早饭呢，’我说。"},{"index":2,"enSha256":"4378ed288be6a73e4a8408fb804bd38cfb10f569cbc36c3138b14f86cf038ab5","zh":"‘你在干什么？’她问。"},{"index":3,"enSha256":"ef92ef009d96e1a26174785c9457d7e63328eae9150fcf9f0c852c2fe3da8944","zh":"‘我在吃早饭，’我又说了一遍。"},{"index":4,"enSha256":"ba859b35de383080f8de46708a34dbd35339a913e45aaf425acfd97dff285439","zh":"‘天哪，’她说，‘你总是起得这么晚吗？现在已经一点了！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l003","book":2,"number":3,"title":"Please send me a card","paragraphs":[{"index":0,"enSha256":"cb28f76a3678b7018404a61cc9c99bfae09f6bf6f03cf5782a482f687ee05d7e","zh":"明信片总会搅乱我的假期。去年夏天我去了意大利，参观了博物馆，也在公园里坐坐。一位友好的服务员教了我几句意大利语，随后又借给我一本书。我读了几行，却一个字也不懂。每天我都想着寄明信片这件事。假期很快就过去了，可我一直没有给朋友们寄明信片。最后一天，我下了一个很大的决心：早早起床，买了三十七张明信片。我在房间里待了一整天，结果一张也没写！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l004","book":2,"number":4,"title":"An exciting trip","paragraphs":[{"index":0,"enSha256":"547ba35c9c057d687c5a323b8fd964d97c3d215b1c0b1e2880e3f25130aa3990","zh":"我刚收到我的兄弟蒂姆的来信。他在澳大利亚，已经在那里待了六个月。蒂姆是一名工程师，正在一家大公司工作，而且已经去过澳大利亚许多不同的地方。他刚买了一辆澳大利亚产的汽车，去了澳大利亚中部的小镇艾丽斯斯普林斯。不久他还要去达尔文，再从那里乘飞机去珀斯。蒂姆以前从来没有出过国，所以他觉得这次旅行十分令人兴奋。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l005","book":2,"number":5,"title":"No wrong numbers","paragraphs":[{"index":0,"enSha256":"86d537d45e2fad3c8bda4545310c20511a16e0a07e8261ed1dc051ca39567cfa","zh":"詹姆斯·斯科特先生在锡尔伯里有一家汽车修理厂，如今又刚在平赫斯特买下了另一家。平赫斯特离锡尔伯里只有五英里，但斯科特先生的新修理厂装不上电话，于是他刚买了十二只鸽子。昨天，一只鸽子把第一条消息从平赫斯特送到了锡尔伯里，飞完这段路只用了三分钟。到目前为止，斯科特先生已用这种办法在两家修理厂之间传递了许多索取零配件的请求和其他急件。他就这样开办起了自己的私人‘电话’服务。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l006","book":2,"number":6,"title":"Percy Buttons","paragraphs":[{"index":0,"enSha256":"27690008df574e67a13ef85be994e364de1c3be66aab468f2af06113af8c7fa0","zh":"我刚搬进桥街的一所房子。昨天，一个乞丐来敲我的门，向我要一顿饭和一杯啤酒。作为回报，他倒立着唱起歌来。我给了他饭吃，他吃了饭，喝了啤酒，随后把一块奶酪放进口袋就走了。后来，一位邻居向我说起了他的事。大家都认识他，他叫珀西·巴顿斯。他每个月都到这条街上的每一家去一次，而且总是要一顿饭和一杯啤酒。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l007","book":2,"number":7,"title":"Too late","paragraphs":[{"index":0,"enSha256":"c2d8922b964f4fdea7acfe85548a78f01b3df49f8ea37dbba55c90513a54f523","zh":"飞机晚点了，侦探们整个上午都在机场等候。他们在等一个从南非运来的贵重包裹，里面装着钻石。几小时前，有人告诉警方，窃贼会设法偷走这些钻石。飞机抵达时，有些侦探守在机场主楼里，另一些则守在停机坪上。两个人把包裹从飞机上取下，搬进了海关大楼。两名侦探在门口警戒，另外两名打开了包裹。让他们吃惊的是，这个贵重的包裹里装的竟然全是石头和沙子！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l008","book":2,"number":8,"title":"The best and the worst","paragraphs":[{"index":0,"enSha256":"10c0f50e1184ac8bf4b90927e319d9d563b5be67d9e660cad38b5ee64192c1d6","zh":"乔·桑德斯拥有我们镇上最漂亮的花园。几乎人人每年都参加‘最佳花园竞赛’，但每次都是乔获胜。比尔·弗里思的花园比乔的大，他也比乔干活更卖力，种了更多的花和蔬菜，可乔的花园更有趣味。他修了整齐的小径，还在池塘上搭了一座木桥。我也喜欢花园，却不喜欢辛苦劳动。每年我也参加花园竞赛，而且总能因为拥有镇上最差的花园而获得一个小奖！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l009","book":2,"number":9,"title":"A cold welcome","paragraphs":[{"index":0,"enSha256":"ac778b6f43d262806ce3d64a6e34986a25a181d30171be393cc835de8de0677d","zh":"星期三晚上，我们去了市政厅。那是一年的最后一天，一大群人聚集在市政厅的大钟下面。再过二十分钟，大钟就要敲响十二点了。十五分钟过去了，就在差五分钟到十二点时，钟停了，巨大的分针一动不动。我们等了又等，始终没有动静。突然有人喊道：‘已经十二点零两分了！钟停了！’我看了看手表，果然如此。那座大钟偏偏不肯迎接新年。就在这时，大家都笑了起来，唱了起来。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l010","book":2,"number":10,"title":"Not for jazz","paragraphs":[{"index":0,"enSha256":"05c85919c9e2d473e8827973955a3313007164da751f41190e28ce16354af80b","zh":"我们家有一件古老的乐器，叫作击弦古钢琴，是一六八一年在德国制造的。它摆在客厅里，在我们家已经有很长时间了，是祖父许多年前买的。最近，一位来访的客人把它弄坏了：她竟想用它来弹爵士乐！她敲键太用力，弄断了两根琴弦。父亲大为震惊。现在我们都不许碰它，父亲的一位朋友正在修理它。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l011","book":2,"number":11,"title":"One good turn deserves another","paragraphs":[{"index":0,"enSha256":"d92dfe74b5afe44a6820869b3b3e4b204a52b36d4afde2895da2321c5abf2078","zh":"我正在一家餐馆吃晚饭，托尼·斯蒂尔走了进来。托尼几年前在一家律师事务所工作，现在在银行上班。他薪水不错，却总是向朋友借钱，而且从来不还。托尼看见我，走过来和我坐在同一张桌旁。他倒从来没向我借过钱。他吃饭时，我请他借给我二十英镑。出乎意料，他立刻把钱给了我。‘我从没向你借过钱，’托尼说，‘现在你可以替我付晚饭钱了！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l012","book":2,"number":12,"title":"Goodbye and good luck","paragraphs":[{"index":0,"enSha256":"0036db38675db0a899851c7f23758b9f945f6a179c477878e87f946b6283448e","zh":"我们的邻居查尔斯·艾利森船长明天要从朴次茅斯启航。我们一大早就到港口去见他。他会在自己的小船‘托普塞尔号’上。‘托普塞尔号’是一艘有名的小船，已经多次横渡大西洋。艾利森船长八点才出发，所以我们的时间很充裕。我们先看看他的船，再向他道别。他将离开两个月。我们为他感到很自豪，因为他要参加一场重要的横渡大西洋比赛。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l013","book":2,"number":13,"title":"The Greenwood Boys","paragraphs":[{"index":0,"enSha256":"238196ba90c5fcc8157e27f982fc7cb7bea77e889cce52ad86f5e70880a6eaac","zh":"‘绿林少年’是一个流行歌曲演唱组合，目前正在全国各地巡演。他们明天就会到这里，乘火车来，镇上的大多数年轻人都会到车站迎接。他们明晚将在工人俱乐部演唱。‘绿林少年’将停留五天，其间演出五场。照例，警察可有得忙了，他们得设法维持秩序。每逢这种场合，情况总是如此。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l014","book":2,"number":14,"title":"Do you speak English?","paragraphs":[{"index":0,"enSha256":"cb0c30991c5464dbed9c143408fbeb649a89a49484490e73d9b809744bb1df6f","zh":"去年我遇到过一件有趣的事。我离开法国南部的一个小村庄，继续开车去下一个城镇。途中，一个年轻人向我招手。我停下车，他问能不能搭我的车。他一上来，我就用法语向他问早安，他也用法语回答。除了几个词，我一点法语也不懂。一路上，我们谁都没有说话。快到镇上时，那个年轻人突然慢慢地问：‘你会说英语吗？’我这才得知，他自己就是英国人！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l015","book":2,"number":15,"title":"Good news","paragraphs":[{"index":0,"enSha256":"7d1fbbb551bbc5f01a3a00fe0b7d896356fa610bb360e0115aa0786e19b0cf3f","zh":"秘书告诉我，哈姆斯沃思先生要见我。走进他的办公室时，我非常紧张。我进去后，他没有从办公桌前抬起头来。我坐下后，他说生意很不景气，公司负担不起这么高的工资了，已经有二十个人离开。我知道，这下轮到我了。"},{"index":1,"enSha256":"a62d4588933144d36319add0f34695952c0aecf747da939ac3c44dda415b0ffc","zh":"‘哈姆斯沃思先生，’我声音微弱地说。"},{"index":2,"enSha256":"97698a29e714421bd9f36e5410570d62b5d490a082aad6853e376293685914fd","zh":"‘别打断我，’他说。"},{"index":3,"enSha256":"637f145eadb4a369054244c50666895f2062c26797e9aec7588b4300a757b3b3","zh":"接着他笑了，告诉我以后每年要给我多加一千英镑！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l016","book":2,"number":16,"title":"A polite request","paragraphs":[{"index":0,"enSha256":"c162853fa1b8e8746c7e383867afd08c7ac745e7da9bc8523b2685c4343a28e2","zh":"如果你把车停错了地方，交通警察很快就会发现。如果他不贴罚单就放你走，那你可真幸运。不过，情况并不总是这样，交警有时也很客气。我在瑞典度假时，发现车上有这样一张便条：‘先生，欢迎您来到本市。这里是禁止停车区域。如果您注意街上的标志，就能在这里过得愉快。这张便条只是一个提醒。’收到这样的请求，你怎么会不照办呢！"}],"reviewStatus":"self-reviewed","translationNotes":["英文源在‘I found this. note’处保留了扫描件的标点或墨迹疑点；此处按句意‘发现这样一张便条’翻译，未修改英文。"]},{"lessonId":"nce-b2-eef57c-l017","book":2,"number":17,"title":"Always young","paragraphs":[{"index":0,"enSha256":"3d2c064641171fce75b46cbd14e310d836bca71b7ab9796c3bd91bca7a1790bc","zh":"我姑妈詹妮弗是个演员，年纪想必至少有三十五岁了。尽管如此，她却常在舞台上扮演少女。不久她又要参演一部新戏，这一次演一个十七岁的姑娘。在戏中，她得穿鲜红的连衣裙和黑色长袜。去年演另一部戏时，她得穿短袜和一条鲜艳的橙色连衣裙。如果有人问起她的年龄，她总是回答：‘亲爱的，长大一定是件可怕的事！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l018","book":2,"number":18,"title":"He often does this!","paragraphs":[{"index":0,"enSha256":"5b6129ee306d3a0ab026d2ea5d5ca2fc451cd7cbc84f596be0d007ff4f701702","zh":"我在乡村一家小酒馆吃过午饭后，开始找我的包。我原先把它放在门边的一把椅子上，可这时却不见了！我正在寻找，店主走了进来。"},{"index":1,"enSha256":"aec078bf88b95e043794b184ab644e0f2998c3c860ea296819ff968870c6873d","zh":"‘饭吃得好吗？’他问。"},{"index":2,"enSha256":"547998d395c511b70819d6cfcaba1b09759ce995b9749ab07e7e09f1f0b1f935","zh":"‘很好，谢谢，’我回答，‘可是我没法付账了，我的包不见了。’"},{"index":3,"enSha256":"eda28777c8a726e6446ebe964a7c5dcfe238dcb74f670e6b283a5bef17d4114f","zh":"店主笑了笑，立刻出去了。几分钟后，他拿着我的包回来，把它还给了我。"},{"index":4,"enSha256":"156447421dc85c3a3044099af6f354954fd794bbb94867da22e4077e1970d78f","zh":"‘实在抱歉，’他说，‘我的狗把包叼到花园去了。它经常这样！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l019","book":2,"number":19,"title":"Sold out","paragraphs":[{"index":0,"enSha256":"53409a34c82e4a527b489acd7c6aa134b64198c51f36652c79077ac85be6584e","zh":"‘戏随时都可能开演，’我说。‘说不定已经开演了，’苏珊回答。我赶到售票处，问：‘请给我两张票，好吗？’‘对不起，票已经卖完了，’售票的姑娘说。‘真遗憾！’苏珊叫道。就在这时，一名男子匆忙来到售票处，问：‘这两张票可以退吗？’‘当然可以，’姑娘说。我马上又回到售票处，问：‘请把那两张票卖给我，好吗？’‘当然，’姑娘说，‘可这是下星期三那场的票，你还要吗？’‘那我就买下来吧，’我沮丧地说。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l020","book":2,"number":20,"title":"One man in a boat","paragraphs":[{"index":0,"enSha256":"6e8f6f17cf6cc66796aa2f115c3ceee94d9bff250e14bd8f06e900f427d22bde","zh":"钓鱼是我最喜欢的运动。我经常钓上几个小时，什么也钓不到，可我并不在意。有些钓鱼的人运气不好，鱼没钓上来，却钓到旧靴子和垃圾。我的运气还不如他们：我什么也钓不到，连旧靴子也没有。每次在河上待了整个上午，我总是提着空袋子回家。‘你该放弃钓鱼了！’朋友们说，‘这简直浪费时间。’可他们没明白一件要紧的事：我其实对钓鱼并不感兴趣，我只喜欢坐在船上，什么事也不干！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l021","book":2,"number":21,"title":"Mad or not?","paragraphs":[{"index":0,"enSha256":"0e67677decd6b58e5e3d5f63532abbe913ec8b97fb5147f979de73b3f13c94f2","zh":"飞机快要把我逼疯了。我住在机场附近，昼夜都能听见飞机飞过的声音。机场多年前就建好了，但当时不知什么缘故没能使用。去年它终于投入使用，想必已有一百多人被噪声逼得搬离了家。我是少数留下来的人之一。有时候我觉得，这栋房子迟早会被飞过的飞机撞倒。有人愿意付给我一大笔钱让我搬走，但我决心留在这里。人人都说我一定疯了，他们大概说得对。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l022","book":2,"number":22,"title":"A glass envelope","paragraphs":[{"index":0,"enSha256":"80a55a841d7cffeccd0fe012b05ba69e312b66fa7d84cf4a7e580a61ef078cba","zh":"我的女儿简做梦也没想到，自己会收到荷兰一位同龄姑娘的信。去年我们乘船横渡英吉利海峡时，简把一张写有自己姓名和地址的纸放进瓶子，扔进了海里。后来她再也没想起这件事，可十个月后，她收到一位荷兰姑娘的来信。现在两个姑娘经常通信，不过她们已决定改用邮局寄信。这样寄信虽然会多花一点钱，但一定快得多。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l023","book":2,"number":23,"title":"A new house","paragraphs":[{"index":0,"enSha256":"a3ff4f295572930f100eee18adeb89dff4e3324cb0459679a030af6e4ed09199","zh":"昨天我收到姐姐的来信。她住在尼日利亚，在信中说她明年要来英国。她若真来，一定会大吃一惊。我们现在住在乡下一栋漂亮的新房子里。姐姐离开以前，房子就已经动工，五个月前才建好。我在回信中告诉她，她可以和我们住在一起。房子有许多宽敞的房间，还有一个可爱的花园。这房子样式很现代，所以在有些人眼里很奇怪。它想必是这一带唯一的现代式房屋。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l024","book":2,"number":24,"title":"It could be worse","paragraphs":[{"index":0,"enSha256":"cf442c2b991d74cab104182e19502b83037c664eb05c42cb1326c97150f8ddfe","zh":"我走进旅馆经理的办公室，坐了下来。我刚丢了五十英镑，心里非常难过。‘我把钱放在房间里，’我说，‘现在却没了。’经理很同情我，却也无能为力。‘这些日子人人都在丢钱，’他说。他开始抱怨这个邪恶的世界，却被一阵敲门声打断了。一个姑娘走进来，把一个信封放在他的桌上，里面装着五十英镑。‘这是我在这位先生的房门外捡到的，’她说。‘看来，’我对经理说，‘这世上还是有诚实的人啊！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l025","book":2,"number":25,"title":"Do the English speak English?","paragraphs":[{"index":0,"enSha256":"181642157bf529e2233072e5a3b2f425c988722a9e9b9d811d700582cf584888","zh":"我终于到了伦敦。火车站又大、又黑、又暗。我不知道去旅馆的路，便向一名搬运工打听。我说英语时不仅十分仔细，而且发音很清楚，可搬运工还是听不懂。我把问题重复了好几遍，他最后才明白。他回答了我，可他说得既不慢，也不清楚。‘我是外国人，’我说。于是他放慢了语速，可我依然听不懂。我的老师从来没这么说过英语！我和搬运工相视而笑。接着他又说了一句话，这回我听懂了。‘你很快就能学会英语的！’他说。我对此很怀疑。在英国，每个人仿佛都说着不同的语言。英国人彼此听得懂，我却听不懂他们的话！他们说的真是英语吗？"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l026","book":2,"number":26,"title":"The best art critics","paragraphs":[{"index":0,"enSha256":"e622f85d1d2586e4f892f01618fc27b78b53cf52012efd975375cb0ddc00384b","zh":"我是学美术的，画过许多画。很多人装作懂现代艺术，总爱告诉你一幅画‘讲的是’什么。当然，许多画根本不‘讲’什么，只是好看的图案。我们喜欢这些画，就像喜欢漂亮的窗帘布一样。我觉得，幼小的孩子往往比任何人都更能欣赏现代绘画，因为他们观察得更多。我妹妹只有七岁，却总能说出我的画好不好。昨天她走进了我的房间。"},{"index":1,"enSha256":"4378ed288be6a73e4a8408fb804bd38cfb10f569cbc36c3138b14f86cf038ab5","zh":"‘你在干什么？’她问。"},{"index":2,"enSha256":"3f7151563ef9cc1945844eb6a1ecf0ae8f082ba4a41b3adcf36db8d04874c3b2","zh":"‘我在把这幅画挂到墙上，’我回答，‘这是新画的，你喜欢吗？’"},{"index":3,"enSha256":"ce1537bad9f0c1a058c846a848585e3c3f25ad4e08f62d2cc75055c78b8f278a","zh":"她挑剔地看了一会儿，说：‘还行，可它是不是挂倒了？’"},{"index":4,"enSha256":"0a27edeff7eb522bb844871ac93f4250e27f65e0de1e1aaf7accb8ee59ec669a","zh":"我又看了一眼。她说得对，还真挂倒了！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l027","book":2,"number":27,"title":"A wet night","paragraphs":[{"index":0,"enSha256":"677796ffef424b4ffcf1d06878a97dee317e996bbf19668a8bb8cb6bfb58e84d","zh":"快到傍晚时，男孩子们在田野中央搭起帐篷。刚搭好，他们就在露天生火做饭。大家都饿了，饭菜闻起来也很香。美美地吃了一顿后，他们围着篝火讲故事、唱歌。可是过了一会儿，天开始下雨了。男孩子们感到疲倦，便把火熄灭，钻进帐篷。睡袋暖和又舒服，大家都睡得很沉。半夜，两个男孩子醒来，叫喊起来：帐篷里全是水！大家都从睡袋里跳出来，急忙跑到外面。雨下得很大，他们发现田野里已经形成了一条小溪。溪水在田间蜿蜒流淌，正好从他们的帐篷底下流过去！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l028","book":2,"number":28,"title":"No parking","paragraphs":[{"index":0,"enSha256":"dca2f1d20ab729d239273c0271c6a93a41e46161d232efb145a5ec713eb95500","zh":"贾斯珀·怀特是少数相信古老神话的人之一。他刚在城里买了一栋新房子，可自从搬进来，就不断受到汽车和车主的困扰。每当他晚上回家，总会发现有人把车停在他家大门外。为此，他自己的车竟一次也没能开进车库。贾斯珀在门外竖起了‘禁止停车’的牌子，却毫无效果。现在，他又在大门上方安了一个丑陋的石头像，那是我见过的最丑的脸之一。我问那是什么，他说那是蛇发女妖美杜莎。贾斯珀希望她能把汽车和车主都变成石头，可到现在，一个也没变成石头！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l029","book":2,"number":29,"title":"Taxi!","paragraphs":[{"index":0,"enSha256":"a2565f53fd25039c5ce97d866a722df5dafdcbe26db03443d35d5aa9da2c1a5a","zh":"本·福西特机长买下了一辆不同寻常的‘出租车’，开办了一项新服务。这辆‘出租车’是一架瑞士制造的小飞机，名叫‘皮拉图斯·波特’。这架出色的飞机能载七名乘客，但最让人惊奇的是，它什么地方都能降落：雪地、水面，甚至犁过的田地。福西特机长的第一位乘客是一位医生，他从伯明翰飞往威尔士山区一个偏僻的村庄。从那以后，福西特机长载着乘客去过许多不寻常的地方。他曾降落在一栋公寓楼的楼顶上，还有一次降落在一个废弃的停车场。他刚拒绝了一位商人的奇怪要求。那人想飞往大西洋中一座孤岛——罗科尔岛，但机长认为这趟行程太危险，没有送他去。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l030","book":2,"number":30,"title":"Football or polo?","paragraphs":[{"index":0,"enSha256":"a495929b3904bb9000d410e1f8ea63b89fb0cae1b8b36f550e97adc4d1d3da6e","zh":"韦尔河是一条小河，穿过我家附近的公园。天气好的下午，我喜欢坐在河边。上星期天天气暖和，我照常去河岸边坐坐。一些孩子在岸上做游戏，河里有人在划船。突然，一个孩子使劲踢了一脚球，球朝一艘经过的小船飞去。岸上的一些人向船里的人大喊，可他没听见。球重重地砸到他身上，他差点掉进水里。我转头看那些孩子，却一个也看不见：他们全跑了！船上的人明白发生了什么以后，笑了起来。他朝孩子们喊了一声，把球扔回了岸上。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l031","book":2,"number":31,"title":"Success story","paragraphs":[{"index":0,"enSha256":"34f3f4152c5b1af8c871597fae53b73ce5e34acbe203d24985cf7d3ae44924af","zh":"昨天下午，弗兰克·霍金斯向我讲起他年轻时的经历。退休以前，弗兰克是一家大公司的负责人，可小时候他只在一家小店干活，工作是修理自行车。那时候，他每天得干十四个小时。他攒了好多年的钱，到一九五八年才买下属于自己的一间小作坊。二十多岁时，弗兰克为飞机制造零配件，当时有两个帮手。几年后，小作坊就发展成了一家大工厂，雇用了七百二十八人。回想起早年的艰辛和漫长的成功之路，弗兰克笑了。门开了，他妻子走进来时，他脸上还带着笑。她是来叫他修孙子的自行车的！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l032","book":2,"number":32,"title":"Shopping made easy","paragraphs":[{"index":0,"enSha256":"2f0ded7f5045c51343a5dfa918fb04dcbcf2bff31e60c27fb9dd5e366f1b9514","zh":"人们不像过去那么诚实了。偷窃的诱惑比以往任何时候都大，尤其是在大商店里。最近，一名侦探监视着一位衣着讲究的妇女，她总在星期一上午到一家大商店去。一个星期一，这位妇女进店时，顾客比平时少，侦探更容易监视她了。她先买了几件小东西，过了一会儿，又挑了店里最贵的连衣裙中的一件，交给一名售货员。售货员尽快替她包好，她便拿起包裹，连钱都没付就走了出去。她被捕后，侦探才发现，那名售货员是她的女儿。这个姑娘每星期都免费‘送’母亲一件连衣裙！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l033","book":2,"number":33,"title":"Out of the darkness","paragraphs":[{"index":0,"enSha256":"150d72852e649dc546f0fa7be0535e40f7322650ae047b15fc30141c71a54f3d","zh":"将近一个星期后，这个姑娘才说得清自己的遭遇。一天下午，她驾着小船从海岸出发，却遇上了风暴。傍晚时，小船撞上礁石，她跳进海里，在水中熬了整整一夜，才游到岸边。那一夜她游了八英里。第二天清晨，她看见前方有灯光。灯光高高地亮在悬崖上，她知道自己靠近海岸了。一上岸，她就挣扎着朝那束灯光爬上悬崖。她能记起的只有这些。一天后醒来时，她发现自己已躺在医院里。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l034","book":2,"number":34,"title":"Quick work","paragraphs":[{"index":0,"enSha256":"54dd7a66a1166d3917b9935f7718f0539a8303a68889882ffa5eb4567a5dedb8","zh":"丹·鲁宾逊整个星期都很担心。上星期二，他收到当地警察的一封信，要他去一趟警察局。丹想不通警察为什么找他。不过，他昨天还是去了，如今已经不再担心。在警察局，一位面带微笑的警察告诉他，他的自行车找到了。警察说，五天前，有人在四百英里以外的一个小村庄发现了这辆车，现在正用火车把它送到他家。丹听了十分吃惊，同时又觉得好笑，因为他从没指望还能找到那辆自行车。那车是二十年前被偷的，当时丹还是个十五岁的男孩子！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l035","book":2,"number":35,"title":"Stop thief!","paragraphs":[{"index":0,"enSha256":"640a3525b51fd44f62e00d19a3b510f35ca5a5a18cb4726037a76b008b4d5711","zh":"罗伊·特伦顿过去开出租车，不久前改当了公共汽车司机，他一点也不后悔，反而觉得新工作刺激多了。最近，他沿着卡特福德街开车时，看见两个窃贼冲出一家商店，朝一辆等着他们的汽车跑去，其中一个提着一袋钱。罗伊马上行动，驾驶公共汽车直冲窃贼而去。提钱的那个人吓得把袋子都扔了。两名窃贼正想开车逃走，罗伊便开着公共汽车撞上了他们汽车的尾部。那辆被撞坏的车开走时，罗伊停下车，打电话报了警。窃贼的车损坏严重，很容易辨认。不久，警察就拦住了那辆车，两个人都被捕了。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l036","book":2,"number":36,"title":"Across the Channel","paragraphs":[{"index":0,"enSha256":"4e91015954cbc0d733c63886f772663b51deeeee8e1cfa5ba3574d046e7e8b52","zh":"黛比·哈特明天要游过英吉利海峡，计划清晨五点从法国海岸出发。她只有十一岁，希望创造一项新的世界纪录。她游泳本领很强，许多人觉得她一定能成功。黛比的父亲将驾一艘小船陪她出发。哈特先生多年来一直训练女儿。明天，女儿长距离游向英国时，他会焦急地注视着她。黛比打算每两小时短暂休息一次，喝些东西，但不吃任何固体食物。她的大多数同学都会在英国海岸等她，黛比的母亲也在其中。她母亲少女时代也曾游过海峡。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l037","book":2,"number":37,"title":"The Olympic Games","paragraphs":[{"index":0,"enSha256":"c3a13ecccbb5893b17d4c313c6128a1bc3152302c8922ba05681463c307b1a97","zh":"四年以后，奥林匹克运动会将在我国举行。由于会有大批游客来到我国，政府将兴建旅馆、一座巨大的体育场和一座符合奥运标准的新游泳池，还将修建新的道路和一条专用铁路线。运动会将在首都近郊举办，整个地区将命名为‘奥运城’。工人们将在今年年底前修好新道路，明年年底前完成新体育场的建设。这些出色的现代建筑由库尔特·冈特设计。新建筑一座座拔地而起时，人人都会满怀期待地关注。我们都十分兴奋，盼望着奥运会，因为我国以前从未举办过奥运会。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l038","book":2,"number":38,"title":"Everything except the weather","paragraphs":[{"index":0,"enSha256":"4f186483f9fe18d221b7accf62ad5d1cec7b3f6aad52035d5e27bbeece9e986d","zh":"我的老朋友哈里森回英国以前，已在地中海地区住了多年。他常梦想退休后回到英国，并打算在乡下定居。他一回来就买了栋房子，住了进去。几乎马上，他就开始抱怨天气：虽然还是夏天，却不停下雨，而且常常冷得刺骨。在阳光下生活了那么多年后，哈里森很不适应，表现得仿佛以前从没在英国住过。到最后，他实在受不了了，还没来得及安顿下来，就卖掉房子，离开了英国。他多年的梦想就此告终。哈里森什么都考虑到了，唯独漏了天气。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l039","book":2,"number":39,"title":"Am I all right?","paragraphs":[{"index":0,"enSha256":"6acd71f6529c6be860d2ab473c2e72102e926500c4b26b918f2ee70352877980","zh":"约翰·吉尔伯特住院时，请医生告诉他手术是否成功，医生却不肯说。第二天，这位病人要了一部床头电话。独自一人时，他拨通医院总机，要求转接米林顿医生。医生接起电话后，吉尔伯特先生说，他想打听一位病人的情况，那人叫约翰·吉尔伯特。他问吉尔伯特先生的手术是否成功，医生告诉他很成功。他又问吉尔伯特先生什么时候可以出院，医生说还得再住两星期。接着，米林顿医生问来电的人是不是病人的亲属。‘不是，’病人回答，‘我就是约翰·吉尔伯特。’"}],"reviewStatus":"self-reviewed","translationNotes":["英文源保留扫描件误拼‘hosptial’，应为‘hospital’；译文按‘医院／住院’的正确词义处理，未修改英文。"]},{"lessonId":"nce-b2-eef57c-l040","book":2,"number":40,"title":"Food and talk","paragraphs":[{"index":0,"enSha256":"33a59b7bc58b79725705b1518436291f5aa9b0616d30fcc5317066a040c4676b","zh":"上周参加一次晚宴时，女主人安排我坐在兰博尔德太太身旁。她身材高大，脸上毫无笑容，穿着一条紧身黑色连衣裙。我在她旁边坐下时，她连头也没抬，眼睛一直盯着盘子，不一会儿就忙着吃起来。我设法找话聊。"},{"index":1,"enSha256":"5bcfa656570a466dd950671c4c4d62ee5da8ecdb093057880251db3c0bc49e8f","zh":"‘环球剧院很快要上演一出新戏，’我说，‘您会去看吗？’"},{"index":2,"enSha256":"163562b8d32b5b38a869a99e1eea6d9dc92a17c6e9f3fc0c629c4c289c341ca5","zh":"‘不会，’她回答。"},{"index":3,"enSha256":"aa5a6f44c96b85202ed7f16b4c44a378cfa7282f45945bf51681e7188668fa3c","zh":"‘您今年打算出国度假吗？’我问。"},{"index":4,"enSha256":"163562b8d32b5b38a869a99e1eea6d9dc92a17c6e9f3fc0c629c4c289c341ca5","zh":"‘不打算，’她回答。"},{"index":5,"enSha256":"3164f81d304cd88a5596c70adb35c54c58d57b951fc5f55c3b74b3f1fa5ff13c","zh":"‘那您会留在英国吗？’我问。"},{"index":6,"enSha256":"163562b8d32b5b38a869a99e1eea6d9dc92a17c6e9f3fc0c629c4c289c341ca5","zh":"‘不会，’她回答。"},{"index":7,"enSha256":"ae91bf466ce123722a930e9fe53db26c532eb99e4743326741384f9b1fa620eb","zh":"我实在没办法了，就问她这顿饭吃得是否愉快。"},{"index":8,"enSha256":"6f0e76ae24e5129024c7c8b9e0018fa19b6242b18036cd5fbce43f71fadb2823","zh":"‘年轻人，’她回答，‘如果你多吃一点、少说一点，我们两个都能吃得愉快！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l041","book":2,"number":41,"title":"Do you call that a hat?","paragraphs":[{"index":0,"enSha256":"dbfc5293a74f99a8b8f148d9d795e3a76253ead2527f98c51752a0c5f54cc8ed","zh":"‘你管那叫帽子？’我对妻子说。"},{"index":1,"enSha256":"7f360ce9bd6894668fc7ef926e3f2fd3a257058d561bfca2c9a790cdfe6b5fb2","zh":"‘你用不着说得这么难听，’妻子一边照镜子一边回答。"},{"index":2,"enSha256":"6b32819975d64d1960ec8dd1b2debd365dd9c6352c8dc666155c472f86598697","zh":"我在一把带孔的现代式椅子上坐下，等着。我们已经在帽子店里待了半小时，妻子还站在镜子前。"},{"index":3,"enSha256":"ae4325f85616402bacc88b602acde805e5d04f45b91512a411e833f28e4cbc14","zh":"‘我们可不能买不需要的东西，’我突然说。我几乎立刻就后悔说了这话。"},{"index":4,"enSha256":"e388b7f827637b7abf8b6a50a460b718ed11c7bbff3fac1cb4758ae7cc2ae645","zh":"‘你这话完全多余，’妻子回答，‘不用我提醒你昨天买的那条难看的领带吧。’"},{"index":5,"enSha256":"35d0e05fe21efd5517330416ce6f4515dff8542cc6b365734e6b6b67288cd945","zh":"‘我觉得它很好看，’我说，‘男人的领带再多也不嫌多。’"},{"index":6,"enSha256":"21dab6555381d9b50e5a74b9d2f533bb6df39cccd827daf27916d9deb505787f","zh":"‘女人的帽子也是再多都不嫌多，’她回答。"},{"index":7,"enSha256":"79a4873afdaa0b3df495c4e7a36ac14313a97c9a5945ef57770a849f92977239","zh":"十分钟后，我们一起走出商店。妻子头上戴着一顶看起来像灯塔的帽子！"}],"reviewStatus":"self-reviewed","translationNotes":["英文源保留扫描件误拼‘musn’t’，应为‘mustn’t’；译文按‘不能／不该’的语义处理，未修改英文。"]},{"lessonId":"nce-b2-eef57c-l042","book":2,"number":42,"title":"Not very musical","paragraphs":[{"index":0,"enSha256":"82dd9a5b3c41f8248b44619a1cdcb36b92cef714e48f314f9ae3fae451f1882f","zh":"我们在老德里的一个集市里走了很久，便停在一处广场上休息。过了一会儿，我们注意到广场另一边有位弄蛇人，带着两个大篮子，于是走过去看看。他一看见我们，就拿起一支嵌满硬币的长笛，打开其中一个篮子。曲子响起，我们这才看到了蛇。蛇从篮子里昂起身，开始随着笛子的摆动而移动。弄蛇人突然吹起爵士乐和现代流行歌曲，让我们十分惊讶。然而，蛇还是慢悠悠地‘跳舞’。显然，它分不出印度音乐和爵士乐的差别！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l043","book":2,"number":43,"title":"Over the South Pole","paragraphs":[{"index":0,"enSha256":"b96c16248c9b562b5148795e2dfcd8315d0767a52f7af7bd029ac0b883ee0e6b","zh":"一九二九年，也就是飞越北极三年之后，美国探险家R.E.伯德首次成功飞越南极。起初，伯德和同伴们拍下了许多脚下群山的照片，但很快就遇上了严重困难。有一阵子，他们的飞机眼看就要坠毁。只有升到一万英尺，飞机才能越过群山。伯德立即命令同伴扔掉两大袋沉重的食物。飞机这才得以上升，从山峰上方四百英尺处飞过。这时伯德知道，他们可以到达三百英里以外的南极了，因为视野中再也没有山。飞机顺利地飞过了无边无际的白色平原。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l044","book":2,"number":44,"title":"Through the forest","paragraphs":[{"index":0,"enSha256":"9cf92405e19f9dc83439cd1cc1a9c76cd4d2a3eb57474e351b6fb190dc3a4f79","zh":"安妮·斯特林太太在树林里追赶两名男子时，根本没想到自己冒着多大的风险。此前，她正和孩子们在树林边野餐，两名男子突然冲上来，想抢她的手提包。争夺中，包带断了，两人拿着包就往林子里跑。斯特林太太气极了，拔腿便追。很快她就气喘吁吁，但仍继续跑。追上时，她看见两人已经坐下来，正翻看包里的东西，便径直冲了过去。那两人吓得丢下包就逃。‘包带得修一修，’斯特林太太后来说，‘不过他们什么也没偷走。’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l045","book":2,"number":45,"title":"A clear conscience","paragraphs":[{"index":0,"enSha256":"12022f1b7e24b3d547b4ee79ad530b9b584ab3990b74b7cf37e636fffa11e927","zh":"一大笔钱丢失的消息，很快传遍了整个村子。当地的肉贩萨姆·本顿把积蓄送往邮局时，丢了钱包。萨姆确信，钱包一定被某个村民捡到了，却一直没人还给他。三个月过去了，一天早晨，萨姆在家门外找到了钱包。它用报纸包着，里面有他丢失钱款的一半，还有一张便条：‘没错，是小偷，不过只算百分之五十的小偷！’两个月后，又有人给萨姆送来一部分钱，附着另一张便条：‘现在只算百分之二十五的小偷了！’过了一段时间，萨姆的钱就这样全部还清。最后一张便条写着：‘我现在是百分之百的老实人了！’"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l046","book":2,"number":46,"title":"Expensive and uncomfortable","paragraphs":[{"index":0,"enSha256":"9db254f54172be5c23b1a7a74b3d3996ff496101c51ac3ca3e04fd0d7e7ea531","zh":"一架从伦敦飞来的飞机抵达悉尼机场后，工人们开始卸下一批装衣服的木箱。其中一个箱子格外重，谁也解释不了原因。一名工人忽然想到打开箱子看看，里面的情形让他大吃一惊：一名男子躺在箱内的一堆毛织品上。他被人发现后惊讶得连逃跑都没试过。被捕后，他承认自己是在飞机离开伦敦前躲进箱子的。这趟旅行漫长而难受，因为他在木箱里被困了十八个多小时。他被勒令支付三千五百英镑的旅费，而正常票价只有两千英镑！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l047","book":2,"number":47,"title":"A thirsty ghost","paragraphs":[{"index":0,"enSha256":"b5c5f54ff6017e9bf280bbf0d67109b1ef4a29e2df99485a0ed7e48f4073b3c4","zh":"伊恩·汤普森先生最近买下的一家酒馆，现在又挂牌出售了。他打算卖掉酒馆，因为那里闹鬼。他告诉我，一天夜里，他听见酒吧间传来怪声，无法入睡。第二天早晨，他发现门被椅子堵住，家具也被挪动了。他睡前明明关了灯，可早上灯却亮着。他还说，他找到了五个空威士忌酒瓶，一定是鬼在前一晚喝光的。我说，也许是一些村民溜进来喝了免费酒，汤普森先生却摇了摇头。村民们已经告诉他，即使他把酒馆白送给他们，他们也不要。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l048","book":2,"number":48,"title":"Did you want to tell me something?","paragraphs":[{"index":0,"enSha256":"7f03de7ca3276ba552800c96ffca33b3af9735dea04c4d5472a9d6736b82cb53","zh":"牙医总爱在你没法回答的时候提问。我的牙医刚拔掉我一颗牙，叫我休息一会儿。我想说点什么，嘴里却塞满了药棉。他知道我收集火柴盒，便问我的收藏是不是又增加了。接着，他又问我兄弟的近况，以及我是否喜欢在伦敦的新工作。回答这些问题时，我不是点头，就是发出奇怪的声音。与此同时，我的舌头一直忙着寻找原来那颗牙所在的空洞。我突然很担心，却什么也说不出来。牙医终于从我嘴里取出药棉时，我才能告诉他：他把牙拔错了。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l049","book":2,"number":49,"title":"The end of a dream","paragraphs":[{"index":0,"enSha256":"30ea330a46cba7b06199f9eee9cbd87831e49b1b9ee5275e6b056f8eb006c56a","zh":"德黑兰有个年轻人厌倦了睡地板，攒了好几年的钱，终于买到一张真正的床。他有生以来第一次拥有了一张带弹簧和床垫的床，心里十分得意。由于天气很热，他把床搬到了自家屋顶上。头两晚他睡得很好，可到了第三晚，突然刮起了风暴。一阵狂风把床从屋顶卷了下去，床重重地砸进下面的院子。直到床撞到地面，年轻人才醒过来。虽然床摔得粉碎，他却奇迹般地毫发无伤。他醒来时，仍然躺在床垫上。他瞥了一眼散落在周围的木头和金属碎片，伤心地捡起床垫，搬回屋里。他把床垫放到地板上，随即又睡着了。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l050","book":2,"number":50,"title":"Taken for a ride","paragraphs":[{"index":0,"enSha256":"643502baf9275b8d2284a5714c77a3f750794d80053b415b69b73d03aeee5680","zh":"我喜欢到乡间旅行，却不喜欢迷路。最近我出去游玩了一趟，但这次行程花的时间比我预计的长。"},{"index":1,"enSha256":"0e01bb3da5d080337320497a32ca41331021b6c294f7056c71aed86efbb31b29","zh":"“我要去伍德福德格林，”我上公共汽车时对售票员说，“可是我不知道那地方在哪儿。”"},{"index":2,"enSha256":"a128fc94264de8f8a99205a3d85d8553b42459cfc815c2f21456499aa47d02fb","zh":"“到哪一站下车，我会告诉你的。”售票员回答。"},{"index":3,"enSha256":"2cae4dee9837376656c52ef326545c58ead6451dafff7969dd1fa059a06f0b9c","zh":"为了好好欣赏乡村风光，我坐在车厢前部。过了一会儿，车停了下来。我环顾四周，惊讶地发现车上只剩我一个乘客了。"},{"index":4,"enSha256":"38bcd9de590cb5bd73af5855589247bbd06f1939b3aad9e05ce83739f626c271","zh":"“你得在这里下车了，”售票员说，“我们就开到这里。”"},{"index":5,"enSha256":"9ceca3096fdf90e2550d3a9b4777ce424c86f547be2d7cc297f781e1a1cdfc45","zh":"“这里是伍德福德格林吗？”我问。"},{"index":6,"enSha256":"b4553818c03d9b213506918a0666e26086a646b62a51ae04051562d8486a9821","zh":"“哎呀！”售票员突然说，“我忘了叫你下车。”"},{"index":7,"enSha256":"1a484f31e82e69c5ca37f2c60f583485fa93b80986b796acf35a336a371ed48d","zh":"“没关系，”我说，“我就在这里下吧。”"},{"index":8,"enSha256":"48827182abc86e55af33f1ed1dcaaf561b299a1ff5fe31ad3aa124c901678ae5","zh":"“我们现在要往回开了。”售票员说。"},{"index":9,"enSha256":"3f98da652f48ba5e74e932f229b2a9d5d80165e05e2fa23d0c6b0361de30b5a0","zh":"“哦，既然这样，我还是留在车上吧。”我回答。"}],"reviewStatus":"self-reviewed","translationNotes":["第7段英文结尾有多余的句点，中文按对话本意处理。"]},{"lessonId":"nce-b2-eef57c-l051","book":2,"number":51,"title":"Reward for virtue","paragraphs":[{"index":0,"enSha256":"856b03973a2de5f59f25baaaf2f7e71090429ab9d5bdd86a62f7277efb141b5b","zh":"我的朋友休一直很胖，但最近胖得实在厉害，于是决定节食。他是一周前开始节食的。首先，他列了一张长长的清单，写上所有不准吃的食物。清单里包括休最爱吃的大多数东西：黄油、土豆、米饭、啤酒、牛奶、巧克力和糖果。昨天我去看他。我按了门铃，看到休仍旧像以前一样胖，一点也不意外。他把我领进房间，慌忙把一个大包裹藏到书桌下面。很明显，他非常尴尬。我问他在干什么，他心虚地笑了笑，随后把包裹放到书桌上。他解释说，自己节食太严格，偶尔也得奖励一下自己。接着，他让我看了包裹里的东西：里面装着五大块巧克力和三袋糖果！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l052","book":2,"number":52,"title":"A pretty carpet","paragraphs":[{"index":0,"enSha256":"1ca4e060ca8ea81536d2ed5976b360ebefc64cc3caa6bf8efc4553274b7fb0f4","zh":"我们刚搬进一所新房子，我整个上午都在忙碌。我一直在设法把自己的新房间整理好。这可不容易，因为我有一千多本书。更糟的是，房间相当小，所以我暂时把书放在地板上。现在，书铺满了地板的每一寸地方，我进出房间竟然得踩着书走。不久前，我的一位姐妹帮我把一个旧书柜搬上楼。她走进我的房间，看见地板上堆着那么多书，大吃一惊。“这是我见过的最漂亮的地毯。”她说。她盯着看了一会儿，又补充道：“你根本不需要书柜。空闲的时候，你可以坐在这里，读这块地毯！”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l053","book":2,"number":53,"title":"Hot snake","paragraphs":[{"index":0,"enSha256":"f6dc480a6ff96ec628fd2bfadc4924003c839d94f501e82bfa6e7e3dcc97e03c","zh":"消防队员终于扑灭了加利福尼亚州的一场森林大火。此后，他们一直在设法查明起火原因。森林火灾常常是由碎玻璃，或人们随手乱扔的烟头引起的。昨天，消防队员仔细检查了地面，却没有找到任何碎玻璃。他们也十分肯定，这场火不是烟头引起的。然而，今天早晨，一名消防队员意外发现了起火原因。他发现，一条蛇的残骸缠在一万六千伏的高压输电线路上。就这样，他解开了这个谜。原因很简单，却十分罕见：一只鸟从地上叼起了那条蛇，后来又把它丢到了电线上。蛇随即缠住电线。它这么一缠，便使火花落到地面，立刻引起了火灾。"}],"reviewStatus":"self-reviewed","translationNotes":["英文 a firemen 的冠词和名词单复数不一致；按后文 He 的单人指代译为“一名消防队员”，不改英文。"]},{"lessonId":"nce-b2-eef57c-l054","book":2,"number":54,"title":"Sticky fingers","paragraphs":[{"index":0,"enSha256":"7aa0445349e6ae78e02ca5028df4710ff2dae49455c0a6e08799b2b7d31f053d","zh":"早饭后，我把孩子们送到学校，然后去商店买东西。我回到家时还很早。孩子们在上学，丈夫在上班，屋里静悄悄的，于是我决定做些肉馅饼。很快，我便忙着把黄油和面粉混在一起，双手不一会儿就沾满了黏糊糊的面团。偏偏就在这时，电话铃响了。真没有比这更烦人的事了。我用两个黏糊糊的手指夹起听筒，一听出是海伦·贝茨的声音，心里顿时发愁。我花了十分钟才说服她过一会儿再打来。终于，我挂上了电话。真是一团糟！手指上、电话上，连门把手上都沾着面团。我刚回到厨房，门铃就响了，那声音大得简直能把死人吵醒。这回是邮递员来了，他要我签收一封挂号信！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l055","book":2,"number":55,"title":"Not a gold mine","paragraphs":[{"index":0,"enSha256":"1c2fa37ad663b8556a78f07a830ec383448341bdfa532350a48c3cbbb07d0526","zh":"最近，找到失落宝藏的梦想差一点就实现了。一种名叫“探宝者”的新机器已经问世，并被用来探测埋在地下的黄金。人们把这台机器用在海边的一个山洞里，据说海盗从前常在那里藏金子。海盗常把黄金埋进洞里，后来却没能取走。一支搜寻队带着新机器走进山洞，希望找到埋藏的财宝。队长正在检查洞口附近的泥土时，机器显示地下有黄金。队员们激动极了，挖了一个两英尺深的坑。他们最后找到的，却是一枚几乎不值钱的小金币。随后，搜寻队把整个山洞彻底搜了一遍，除了一只空铁皮箱，什么也没找到。尽管如此，许多人仍相信，“探宝者”不久就可能找到有价值的东西。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l056","book":2,"number":56,"title":"Faster than sound!","paragraphs":[{"index":0,"enSha256":"c5036bfc64e24850f0f568562bfe7abc871cec9351809b7f5e77298749137f27","zh":"每年都要举行一次老爷车比赛。去年，许多汽车报名参赛，比赛开始前，现场十分热闹。最漂亮的汽车之一是一辆劳斯莱斯“银魅”。最特别的是一辆只有三个轮子的奔驰车。这辆车造于1885年，是参赛车辆中年代最久的。一阵阵响亮的爆鸣声过后，比赛开始了。许多汽车在赛道上抛了锚，有些司机钻在车底下修车的时间，比坐在车里的时间还多！不过，还是有几辆车跑完了全程。获胜的那辆车达到了每小时四十英里的速度，比任何对手都快得多。比赛快结束时，它飞快地冲下斜坡，司机费了很大劲才把它停住。这场比赛给大家带来了许多欢乐。它与现代赛车比赛大不相同，却同样令人兴奋。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l057","book":2,"number":57,"title":"Can I help you, madam?","paragraphs":[{"index":0,"enSha256":"21b681118d9e8c5d8f9cbd2ea5677c21a2e819a2bdbf82465cf42d8572a77b63","zh":"一位穿牛仔裤的女士站在一家高档商店的橱窗前。她犹豫了片刻，最后还是走进店里，要求看看橱窗里的一件连衣裙。接待她的店员不喜欢她的穿着。他轻蔑地瞥了她一眼，告诉她那件裙子已经卖掉了。女士生气地走出商店，决定第二天教训一下这个店员。第二天早晨，她穿着皮大衣回到店里，一手提着手袋，另一手拿着一把长柄雨伞。她找到那个无礼的店员，要求看同一件连衣裙。店员没有认出她，这次十分热情地为她服务。他好不容易爬进橱窗，把那件裙子拿了出来。女士一看到裙子，就说不喜欢。她兴致勃勃地让店员几乎把橱窗里的所有东西都拿了出来，最后才买下她一开始就指名要的那件裙子。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l058","book":2,"number":58,"title":"A blessing in disguise?","paragraphs":[{"index":0,"enSha256":"ea8b0a8fc0489ce3485c84f835229bad02ac069e6b252dffb9a78fbfc2a19b7e","zh":"据说，弗林利这个小村庄里有一棵“受了诅咒的树”。由于一家报纸提到了这棵树，现在到弗林利来的人多了起来。这棵树是五十年前种在教堂附近的，但只是近几年才有了不祥的名声。据说，谁要是碰了这棵树，就会倒霉；谁要是摘下一片叶子，就会死去。许多村民相信，这棵树已经夺走了好几个人的性命。有人请牧师让人把树砍掉，但到目前为止，他一直拒绝这样做。他指出，这棵树能带来收入，因为全国各地的游客都赶来看它。尽管有这些说法，游客们仍然摘树叶，在树干上刻下自己的名字。到现在为止，他们中还没有一个人突然死去！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l059","book":2,"number":59,"title":"In or out?","paragraphs":[{"index":0,"enSha256":"b28ce918625bc6d52eb1ab195ab02d8bac73538e87e3a0fd32b25fe611aace2d","zh":"我们家的狗雷克斯以前常坐在大门外面叫。每当它想进花园时，就一直叫到有人把门打开为止。邻居们抱怨太吵，于是我丈夫花了好几个星期，训练它用爪子按门闩，自己开门进来。雷克斯很快就成了开门能手。可是上周我出门买东西时，却看见它在花园里靠近大门的地方。这一回，它叫个不停，是要人把它放出去！从那以后，它又养成了一个坏习惯。它一从外面打开门进了花园，就等着门关上。然后它坐在那里叫，直到有人把它放出去。出去后，它立刻又自己开门进来，接着再叫。昨天，我丈夫把大门拆掉了，雷克斯气坏了，从那以后我们就再也没见到它。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l060","book":2,"number":60,"title":"The future","paragraphs":[{"index":0,"enSha256":"e7dce5188bf11197a88974396ef93d427fa8acbf9e19f4d771eceb2d1cbc6cd8","zh":"在一次乡村集市上，我决定去找一位叫贝林斯基夫人的算命者。我走进她的帐篷，她让我坐下。我给了她一些钱后，她望着一个水晶球说：“你的一位亲戚要来看你。她今天傍晚就会到，打算住几天。你一离开这顶帐篷，就会大吃一惊。一位你很熟悉的女人会向你跑来。她会跟你说话，然后领你离开这里。就这些。”"},{"index":1,"enSha256":"bfb0868099c710c1481a7b23df045c1a8a055f5c47a8cf92ed4f8ffef0234a49","zh":"我一走出帐篷，就把贝林斯基夫人的话全忘了，因为我的妻子正急匆匆地朝我走来。“你躲到哪儿去了？”她不耐烦地问，“你的那位姐妹不到一个小时就到了，我们得去车站接她。我们已经晚了。”她转身走开，我便跟着她离开了集市。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l061","book":2,"number":61,"title":"Trouble with the Hubble","paragraphs":[{"index":0,"enSha256":"7724ad295764b17396268309b379bc5276e766b66d753b87ba445acf4ef07a5f","zh":"哈勃望远镜于1990年4月20日由美国国家航空航天局发射升空，耗资超过十亿美元。从一开始，哈勃就出了问题。它传回的图像让人十分失望，因为它的主反射镜有缺陷！现在，美国国家航空航天局打算把望远镜修好，因此不久就会把四名宇航员送上太空进行维修。“奋进”号航天飞机将把宇航员送到哈勃那里。“奋进”号上的机械臂会抓住望远镜并将它固定住，让宇航员进行必要的维修。当然，哈勃位于地球大气层之外，因此很快就会向我们传回前所未有的清晰图像，展现恒星和遥远的星系。哈勃将告诉我们许多有关宇宙年龄和大小的事情。等你读到这篇文章时，哈勃那双锐利的“鹰眼”应该已经向我们传回成千上万张精彩的照片了。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l062","book":2,"number":62,"title":"After the fire","paragraphs":[{"index":0,"enSha256":"a500226d38b074995aeb227a77a8e1c30e2871338b2e11f7dcdcb44c4486b201","zh":"消防队员与这场森林大火搏斗了将近三个星期，才把火势控制住。不久以前，周围绵延数英里的乡野还被参天大树覆盖着。如今，荒凉的山坡上，仍有烟从温热的地面升起。冬天快到了，这些山坡给周围的村庄带来了毁灭的威胁，因为大雨不仅会冲走泥土，还会造成严重的洪水。大火终于扑灭后，林业部门订购了数吨一种生长迅速的特殊草籽。飞机把大量草籽撒到地面上。飞机播撒草籽将近一个月时，天开始下雨。不过到了那时，许多地方的草已经扎下了根。过去几个世纪间长着参天大树的地方，如今在焦黑的泥土上，已经开始出现一片片新绿。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l063","book":2,"number":63,"title":"She was not amused","paragraphs":[{"index":0,"enSha256":"1ab96734e1af4216a85797acfe161081c2146084563cfabcbee76455522ff7a9","zh":"杰里米·汉普登的朋友圈很广，在聚会上很受欢迎。人人都佩服他出众的幽默感——确切地说，除了他六岁的女儿珍妮以外，人人都是如此。最近，杰里米一位最要好的朋友请他在婚宴上讲几句话。这正是杰里米最喜欢的事。他认真准备了讲话，带着珍妮去参加婚礼。他在讲话里穿插了许多有趣的故事，当然大获成功。他刚讲完，珍妮就告诉他，她想回家。杰里米有些失望，不过还是照女儿的意思做了。回家路上，他问珍妮喜不喜欢他的讲话。让他吃惊的是，她说不喜欢。杰里米问她为什么，她告诉他，自己不喜欢看到那么多人嘲笑他！"}],"reviewStatus":"self-reviewed","translationNotes":["英文 everybody. that is 的句点将插入语截断；按上下文“除六岁女儿外人人如此”翻译，不改英文。"]},{"lessonId":"nce-b2-eef57c-l064","book":2,"number":64,"title":"The Channel Tunnel","paragraphs":[{"index":0,"enSha256":"0472652828fdc5220932f4f16bf732ee7cba65dcde65c35e6edecc7ad4e1a681","zh":"1858年，一位法国工程师艾梅·托梅·德·加蒙带着一项计划来到英国，打算在英吉利海峡下面修建一条二十一英里长的隧道。他说，可以在海峡中央建造一个平台。这个平台将兼作港口和火车站。如果在海面上方建造高高的通风烟囱，隧道内就能保持良好的通风。1860年，一位名叫威廉·洛的英国人提出了一个更好的方案。他建议修建两条并行的铁路隧道。这会解决通风问题，因为火车驶入一条隧道时，会从后方带入新鲜空气。四十二年后，隧道工程真的开工了。如果当时英国人不是担心遭到入侵，隧道本来就能修成。世界又等了将近一百年，才等来海峡隧道。它于1994年3月7日正式开通，终于把英国与欧洲大陆连接起来。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l065","book":2,"number":65,"title":"Jumbo versus the police","paragraphs":[{"index":0,"enSha256":"a7d389d2998453e6b8f9a96311c75b2220eab5a47950629be6a3de2705a1058c","zh":"去年圣诞节，马戏团老板吉米·盖茨决定给一家儿童医院送些礼物。他装扮成圣诞老人，在六位漂亮姑娘组成的“仪仗队”陪同下，骑着一头叫江伯的小象，沿着城里的主要街道出发了。他本该知道，警察绝不会允许这种事发生。一名警察走到吉米面前，告诉他本来应该走一条小街，因为江伯挡住了交通。虽然吉米同意马上离开，江伯却不肯挪动。十五名警察费了很大力气，才把它推出主要街道。警察们忙得够呛，却觉得十分有趣。一名警察事后说：“江伯肯定有好几吨重，幸好我们不必抬着它走。当然，我们应该把它抓起来，不过考虑到它一贯表现良好，这回就放它一马吧。”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l066","book":2,"number":66,"title":"Sweet as honey!","paragraphs":[{"index":0,"enSha256":"8dbcd3db2156d48f631f314e214fd3f42739b1d098ce1a8e34526dab5806354c","zh":"1963年，一架兰开斯特轰炸机坠毁在瓦利斯岛上。那里位于南太平洋，是萨摩亚以西很远的一处偏僻地方。飞机损坏得不算严重，但多年来，这起坠机事件渐渐被人遗忘，飞机残骸也一直没有受到扰动。后来到了1989年，也就是坠机二十六年后，人们在对该岛进行一次航空勘测时，意外地重新发现了这架飞机。到这时，保存状况还算良好的兰开斯特轰炸机已经很罕见，值得抢救。法国有关部门让人把飞机分拆包装，运回法国。现在，一群爱好者准备请人修复这架飞机。它有四台劳斯莱斯“梅林”发动机，不过他们只需翻修其中三台。可以想象，当他们打开包装箱，发现第四台发动机竟然甜如蜂蜜，而且仍然完好无损时，会有多么惊喜。一群蜜蜂把发动机变成了蜂巢，它被蜂蜡完整地保存了下来！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l067","book":2,"number":67,"title":"Volcanoes","paragraphs":[{"index":0,"enSha256":"1826aa920832069e9c61dcad4821ab4b05c87189c6691e7e59ae5b27d308d188","zh":"波兰科学家哈鲁恩·塔齐耶夫一生都在研究世界各地的活火山和深洞。1948年，他前往刚果的基伍湖，观察一座新出现的火山，后来把它命名为基图罗。在火山猛烈喷发时，塔齐耶夫竟能把营地扎在离火山很近的地方。虽然他拍到了许多精彩的照片，却无法在火山附近久留。他发现，一股熔岩正像河流一样朝他涌来，眼看就要把他完全包围，但塔齐耶夫设法及时逃脱了。他等到火山平静下来，两天后才得以返回。这一次，他设法爬进基图罗的火山口，以便拍照并测量温度。塔齐耶夫经常这样冒着生命危险工作。对于活火山，他向我们提供的知识，比当今世上任何人都多。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l068","book":2,"number":68,"title":"Persistent","paragraphs":[{"index":0,"enSha256":"4d19d68ade218ee1e2e47b186e6937b0fba8beef14a5bd0d51540c8ebbd1b9d2","zh":"我走到马路对面，想避开他，可他还是看见了我，向我跑来。再假装没看见他已经没用了，于是我向他挥了挥手。我从来都不喜欢遇到奈杰尔·戴克斯。他总是无事可做。不管你多忙，他总要坚持跟着你。我得想个办法，免得他整个上午都跟在我身边。"},{"index":1,"enSha256":"1ad7ae64fc1ae075d9f1d431fa3947e3bfc6b04f2c41c2e9a53cc50b09a95d5b","zh":"“你好，奈杰尔，”我说，“真没想到会在这里碰见你！”"},{"index":2,"enSha256":"6a67d160c8a4e9669edd0e316f84e37362b891d74f4a0dccc6860780ef5e8cc9","zh":"“嗨，伊丽莎白，”奈杰尔回答，“我刚才还在琢磨这个上午该怎么过，直到看见了你。你没忙什么事吧？”"},{"index":3,"enSha256":"82ffb0a1f8e05b7fd75d3737e2644b8795f0686a57c4b8b7886a2532054fe555","zh":"“没有，一点也不忙，”我回答，“我正要去……”"},{"index":4,"enSha256":"f47f96bac36cf093e90f0b817f3947ac02740df9553731790725000900c33fef","zh":"我还没说完，他就问：“我跟你一起去，你介意吗？”"},{"index":5,"enSha256":"9e52f3730ce44da80b71b1c70fef1ecee9e1023066b25246cc957b58f0ca4a8b","zh":"“一点也不介意，”我撒谎说，“不过，我要去看牙医。”"},{"index":6,"enSha256":"424cb9b84d1852f5a3ba107544798783668939702fb1094019b2a0adc2e1f601","zh":"“那我就跟你一起去，”他回答，“候诊室里总有很多东西可以看！”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l069","book":2,"number":69,"title":"But not murder!","paragraphs":[{"index":0,"enSha256":"8713532a24475bc6f08c0ac344c2fe50f28a1940331decb6cd8c886df6fd1aa7","zh":"我第三次参加驾驶执照考试。考官让我在车流繁忙的路段开车，我顺利地完成了。接着，他指示我把车开出城，我开始有了信心。我确信自己已经通过，几乎开始享受这场考试了。考官一定对我的表现很满意，因为他微笑着说：“就剩最后一项了，伊姆斯先生。假设有个孩子突然从你前面横穿马路。我一敲车窗，你就必须在五英尺内把车停住。”我继续开着车，过了一会儿，考官用力敲了敲车窗。虽然声音听得很清楚，我却过了很久才反应过来。我突然用力踩下刹车踏板，我们俩都被向前甩了出去。考官难过地望着我，用悲伤的语气说：“伊姆斯先生，你刚才已经把那个孩子撞死了！”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l070","book":2,"number":70,"title":"Red for danger","paragraphs":[{"index":0,"enSha256":"70701c24247ddf9ef41389eb16cb29761c98a8c9d5982724c24a98bf78349431","zh":"一场斗牛正在进行时，一个醉汉突然晃进了斗牛场中央。观众们大声叫喊起来，可醉汉浑然不知危险。当时，公牛正忙着对付斗牛士，却突然看见了那个醉汉；醉汉一边骂骂咧咧，一边挥舞着一顶红帽子。公牛似乎对批评十分敏感，把斗牛士全忘了，径直朝醉汉冲去。观众突然安静下来。然而，醉汉似乎对自己十分有把握。公牛冲到跟前时，他笨拙地往旁边一闪，让公牛冲了过去。观众爆发出欢呼，醉汉还鞠了一躬。不过这时，已经有三个人进了斗牛场，很快把醉汉拖到了安全的地方。连公牛似乎也对他产生了同情，一直带着同情的神情望着，直到醉汉离开危险区域，才再次把注意力转回斗牛士。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l071","book":2,"number":71,"title":"A famous clock","paragraphs":[{"index":0,"enSha256":"c55ab90b6df24adabd84be639bfaa95a9f5dc55c13fc7c810bc7ed820dd57b43","zh":"到伦敦游览时，你最先看到的景物之一，就是著名的大本钟。世界各地的人们都能通过英国广播公司听到它的钟声。要不是议会大厦在1834年被烧毁，这座大钟本来就不会建造。新议会大厦兴建时，本杰明·霍尔爵士负责监造大钟，大本钟就是以他的名字命名的。它不仅体积巨大，而且走时极其准确。格林尼治天文台的工作人员每天请人校对两次。通过英国广播公司，你能实时听到大钟报时，因为麦克风与钟楼相连。大本钟极少出差错。不过，有一次，它却没能报出准确的时间：一位在钟楼上干活的油漆工把一罐油漆挂在一根指针上，使钟走慢了！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l072","book":2,"number":72,"title":"A car called Bluebird","paragraphs":[{"index":0,"enSha256":"002a4ae47656e9f92ab7cecff10215263d6cc76b049ffbb816dbc665bd1c569d","zh":"著名赛车手马尔科姆·坎贝尔爵士，是第一个把车开到时速超过三百英里的人。1935年9月，他在犹他州的邦纳维尔盐滩创下了新的世界纪录。他驾驶的“蓝鸟”赛车是专门为他制造的，车长超过三十英尺，装有一台两千五百马力的发动机。虽然坎贝尔一度达到每小时三百零四英里以上的速度，但在第一次试跑时，一只轮胎爆了，他很难控制住汽车。这次尝试过后，坎贝尔得知自己的平均时速只有二百九十九英里，非常失望。然而，几天后，有人告诉他，先前的计算出了错，他的平均时速其实是三百零一英里。从那以后，赛车手们已经达到了每小时六百英里以上的速度。多年后，马尔科姆爵士的儿子唐纳德追随父亲的脚步，也创下了一项世界纪录。和父亲一样，他驾驶的汽车也叫“蓝鸟”。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l073","book":2,"number":73,"title":"The record-holder","paragraphs":[{"index":0,"enSha256":"fcbf390e34c984150b58e1c7243741d5ba968b20691c1dc5e7b8ca5027b24a68","zh":"逃学的孩子往往缺乏想象力。安安静静钓上一天鱼，或者在电影院里待八个小时，把同一部电影看上一遍又一遍，通常就是他们所能想到的最大花样了。然而，一个在逃学期间旅行了一千六百英里的男孩，让他们全都相形见绌。他搭便车到了多佛，傍晚时走上一条船，想找个地方睡觉。第二天早晨醒来时，他发现船已在这段时间里驶到了加来。他偷偷溜下船时，没有人注意到他。从那里，他搭上一辆卡车前往巴黎。司机给了他几块饼干和一杯咖啡，把他留在巴黎城外不远的地方。男孩接着拦下的那辆车，并没有像他希望的那样把他带进巴黎市中心，而是把他带到了法国和西班牙边境上的佩皮尼昂。在那里，他被一名警察带走，并由当地有关部门送回英国。他无疑为成千上万梦想逃学的孩子创下了一项纪录。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l074","book":2,"number":74,"title":"Out of the limelight","paragraphs":[{"index":0,"enSha256":"3fb42c2303ac1590aacc96e187d6105de85560856d57cca9321fbe482eb8a56e","zh":"一辆破旧的公共汽车停在一条干涸的河床旁，一群著名的男女演员下了车。他们戴着墨镜，穿着旧衣服，特意做了防备，免得有人认出他们。不过，他们很快就发现，有时伪装也会太成功。"},{"index":1,"enSha256":"51409edf4e30a03cd802ae7050576e470627a882569c59af17d3ef336b5695bd","zh":"“这里真是个野餐的好地方。”格洛丽亚·格利姆说。"},{"index":2,"enSha256":"feb9c919284c79d9ef5b85a35d46f54d1b256b7eae5dbd4696d8aff12433b84f","zh":"“再好不过了，格洛丽亚，”布林克斯利·米尔斯赞同道，“没有记者，也没有影迷！我们为什么不常来呢？”"},{"index":3,"enSha256":"0241dba9db15357d1fb460cf2fda0435984134f0bac1d49bbb4d327220e8c94c","zh":"与此同时，另外两名演员罗克沃尔·斯林格和默林·格里夫斯，已经把两大篮食物搬到了几棵树下的阴凉处。大家刚舒舒服服地安顿好，一个陌生人就出现了。他看起来非常生气。“你们都给我离开这里！”他大声喊道，“我是这里的警长。看见那块告示了吗？上面写着‘禁止露营’——我怕你们不识字，特意告诉你们！”"},{"index":4,"enSha256":"2bbee12a80aa76aac1a2e7fcdf9b04cc5b0b0af166b3c0ef3223d59b7e33984a","zh":"“听我说，警长，”罗克沃尔说，“别对我们这么不客气。我是罗克沃尔·斯林格，这位是默林·格里夫斯。”"},{"index":5,"enSha256":"5d9b19c97aebfb78e94284f325ea932cbb3143b2de8a1a5b9555f25744e5914e","zh":"“哦，是吗？”警长冷笑着说，“那么，我就是布林克斯利·米尔斯，我还有个名字叫格洛丽亚·格利姆。现在，你们赶快给我走！”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l075","book":2,"number":75,"title":"SOS","paragraphs":[{"index":0,"enSha256":"37ace6e275e70586f186b39dca1da9d7db3543f9f8f5e03948079d03924d156c","zh":"前些时候，一架轻型客机偏离航线，坠毁在山区，飞行员丧生。机上仅有的乘客是一位年轻母亲和她的两个幼小女儿，她们都没有受伤。那时正值隆冬，地上积着厚厚的雪。这位母亲知道，最近的村庄也在数英里之外。天黑下来时，她把一只手提箱当作床，把孩子们放进去，再用能找到的所有衣服盖住她们。夜里，天气冷得厉害。她尽可能紧挨着孩子们，甚至想自己也钻进箱子，可箱子实在太小。第二天一早，她听到飞机从头顶飞过，琢磨着该怎样发出信号。接着，她有了主意，在雪地里踩出了“SOS”几个字母。幸运的是，一名飞行员看到了这个信号，用无线电把消息发给了最近的城镇。没过多久，一架直升机就赶到现场，救起了空难幸存者。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l076","book":2,"number":76,"title":"April Fools’ Day","paragraphs":[{"index":0,"enSha256":"4fa8fab4033df9b0e08e46ac172806e8d834fcfaa745bfb5deb49f64ee2b7d17","zh":"“在本次特别新闻简报结束之前，”电视播音员的声音说道，“我们把镜头转到卡拉布里亚的通心粉田。这个地区种植通心粉已经有六百多年了。两位主要种植户朱塞佩·摩尔多瓦和里卡尔多·布拉班特告诉我，他们一直盼望今年获得大丰收，收割也比往年提早开始了。这里可以看到两位工人，他们俩刚刚合力割下了三车金棕色的通心粉秆。全村的人都在日夜忙碌，赶在九月的雨季到来之前，收割、脱粒今年的作物。右边可以看到布拉班特夫人本人。她帮丈夫干活，到现在已有三十年了。布拉班特夫人正在和当地工厂的经理谈话，收下的通心粉就是在那家工厂加工的。最后这个场景向大家展示收获结束时将举行的活动：著名的卡拉布里亚吃通心粉比赛！现任冠军弗拉特利先生从1991年以来，每年都赢得这项比赛。今天是4月1日，星期四，我们的特别新闻简报到此结束。现在把画面交回演播室。”"}],"reviewStatus":"self-reviewed","translationNotes":["按愚人节特别报道的诙谐虚构口吻翻译，保留“种植、收割通心粉”等原文内容。"]},{"lessonId":"nce-b2-eef57c-l077","book":2,"number":77,"title":"A successful operation","paragraphs":[{"index":0,"enSha256":"306e49202f30fbe41edcf5d6353776e0f212195fda8406298cf28ad736550d90","zh":"一具属于公元前800年去世的埃及妇女的木乃伊，刚刚接受了一次手术。这具木乃伊属于谢彭穆特，她曾是底比斯神庙的一名歌者。由于给木乃伊拍摄的X光片上出现了一些奇怪的斑痕，医生们一直想查明，这名妇女是否死于一种罕见疾病。要弄清这一点，唯一的办法就是动手术。手术持续了四个多小时，过程十分困难，因为木乃伊的皮肤上覆盖着坚硬的树脂。医生们从木乃伊上取下一部分组织，送到实验室。他们还发现了一件X光片没有显示的东西：一尊小小的杜阿姆特夫神蜡像。这个长着牛头的神像，通常被放在木乃伊体内。医生们还没有确定这名妇女的死因。他们曾担心，剖开木乃伊时，它会碎成片片，不过幸运的是，并没有发生这种事。这具木乃伊成功地经受住了手术。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l078","book":2,"number":78,"title":"The last one?","paragraphs":[{"index":0,"enSha256":"fc070160134c995f0769cc8f45b5fd64f7fa3573bb058108c18a26ba0a49dbc0","zh":"读完一篇题为《吸烟与你的健康》的文章后，我点起一支烟，让自己镇定下来。我专心而愉快地抽着，因为我确信这将是自己最后一支烟。整整一个星期，我一支烟也没抽，而在这期间，我妻子可受了大罪。我出现了戒烟者常有的各种症状：脾气暴躁，胃口大得惊人。朋友们不停地递给我香烟和雪茄。每当我从口袋里掏出一包糖果，他们都毫不掩饰地笑起来。这样过了七天后，我去参加一次聚会。周围人人都在吸烟，我觉得浑身不自在。老朋友布赖恩劝我拿一支烟时，我再也抵挡不住了。我心虚地接过一支，点上后心满意足地抽了起来。妻子很高兴，一切终于又恢复正常了。不管怎么说，正如布赖恩指出的，戒烟是世界上最容易的事。他自己就已经戒过很多次了！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l079","book":2,"number":79,"title":"By air","paragraphs":[{"index":0,"enSha256":"fb8339994fbac3f48500a96ec7d264c5ef73722317cb3fdbbab06f466aa3651c","zh":"小时候，我常常乘飞机旅行。父母那时住在南美洲，每逢假期，我便从欧洲坐飞机到那里去。总有一名乘务员照看我，我从未有过不愉快的经历。我早已习惯乘飞机，只有一次感到过害怕。起飞后，飞机低低地飞过城市，正在慢慢爬升，突然掉头飞回机场。等候降落时，一名乘务员让我们保持镇静，飞机一着陆，就安静地下机。机上人人都很担心，急于知道发生了什么事。后来我们才知道，机上有一位非常重要的人物。警方接到消息，说有人在飞机上放了炸弹。我们着陆后，飞机接受了彻底搜查。幸运的是，什么也没有发现，五个小时后，我们得以再次起飞。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l080","book":2,"number":80,"title":"The Crystal Palace","paragraphs":[{"index":0,"enSha256":"b0256abf240fd47784bbe249d19a6cf05893b323a8e465b791a4853b41779180","zh":"十九世纪最不同寻常的建筑，也许就是水晶宫。它建在海德公园里，是为1851年的万国博览会而建的。水晶宫不同于世界上其他所有建筑，因为它是用铁和玻璃建成的。它是有史以来规模最大的建筑之一，吸引了许多国家的大批游客。世界各地的各种商品被运来参展，现场还陈列着大量机器。其中最令人赞叹的是内史密斯的蒸汽锤。尽管那时旅行不像今天这样方便，汽船仍载着成千上万的游客，从欧洲横渡英吉利海峡来到英国。他们一到英国，便乘火车前往水晶宫。参观者总计有六百万人，博览会的利润后来被用来建造博物馆和学院。之后，水晶宫被迁到了伦敦南部。在1936年被大火烧毁以前，它一直是世界上最著名的建筑之一。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l081","book":2,"number":81,"title":"Escape","paragraphs":[{"index":0,"enSha256":"3ca17c034ea7f488e4a2c65945a954fb678d8bb31a63ad30ca1993b9f24ec797","zh":"那名战俘杀死卫兵后，迅速把他拖进灌木丛。他在黑暗中飞快地行动，很快换上了死者的衣服。此时，他身穿蓝色制服，肩扛一支步枪，大模大样地在营地前来回走动。他能听见营地里面的喊叫声。那里灯火通明，人们四处奔跑：他们刚刚发现有一名战俘逃走了。就在这时，一辆黑色大轿车停在营地门口，车里坐着四名军官。军官们下了车，经过战俘面前时，他立正敬礼。等他们走后，司机朝他走了过来。这个人显然想聊几句。他年纪已经不小，头发灰白，蓝眼睛清澈。战俘心里有些同情他，却也别无选择。司机刚走近，战俘便用力一击，把他打倒在地。随后，战俘跳上汽车，以最快的速度开走了。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l082","book":2,"number":82,"title":"Monster or fish?","paragraphs":[{"index":0,"enSha256":"a0e8f41cfe18f2e6b4832ffbe3bf0b60f39b5db7f67832c1a4d2cf3038e67d8c","zh":"渔民和水手有时声称，在海里见过怪物。虽然人们常常嘲笑海员讲的这些故事，但现在已经知道，那些偶尔被人看见的“怪物”，许多其实只是奇特的鱼。偶尔会有不寻常的生物被冲到岸上，但人们很少能在外海捕获它们。然而，前些时候，人们在马达加斯加附近捕到了一条奇鱼。这条力大无比的鱼拽着钓线，把一条小渔船拖到了数英里外的海中。渔夫意识到它绝不是普通的鱼，于是竭力避免以任何方式伤害它。等鱼终于被运到岸上，人们发现它有十三英尺多长。它的头长得像马，长着一双蓝色大眼睛，银色的皮肤闪闪发亮，还有一条鲜红的尾巴。后来，这条鱼被送进一家博物馆，正由一名科学家研究。这种鱼叫皇带鱼。它们生活在六百英尺深的海中，因此人类极少见到它们活着的样子。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l083","book":2,"number":83,"title":"After the elections","paragraphs":[{"index":0,"enSha256":"71c52f40af01281a5fc1d5d16267dcfe9ec35421d5cd88abef283124ea796885","zh":"前首相温特沃思·莱恩先生，在最近的选举中落败。现在，他正退出政治生活，并已去了国外。我的朋友帕特里克，一向狂热地反对莱恩先生的激进进步党。选举结束后，帕特里克去了前首相家。他问莱恩先生是不是住在那里，值班警察告诉他，前首相自从败选后就去了国外。第二天，帕特里克又去了那所房子。同一名警察正从门口慢慢走过，帕特里克又问了同样的问题。这一回，警察虽然有些起疑，还是给了他同样的回答。第三天，帕特里克再次来到那所房子前，又问了完全一样的问题。这回，警察发火了。“我昨天和前天都告诉你了，”他大声喊道，“莱恩先生在选举中落败了。他已经退出政坛，到国外居住去了！”"},{"index":1,"enSha256":"0ee494d2c20b274503970f6d3756ace12544cb8eadd01a9d18b979e35d40ece9","zh":"“我知道，”帕特里克回答，“可我就是喜欢听你这样说！”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l084","book":2,"number":84,"title":"On strike.","paragraphs":[{"index":0,"enSha256":"6e2ace290bf43985868337b8d75c17676ab3cbc61240fc056e391c3dc56dc661","zh":"公共汽车职工们决定下周罢工。罢工定于星期二开始，没人知道会持续多久。职工们声明，罢工将一直持续到大家就工资和工作条件达成一致为止。大多数人认为，这次罢工至少会持续一周。许多私家车车主打算在自己上班的路上，免费搭载同样要去上班的人。这将在一定程度上减轻火车的压力。同时，一些大学生自愿在罢工期间驾驶公共汽车。这些学生都很擅长开车，但在驾驶任何一辆公共汽车之前，必须通过一项专门考试。他们将在两天后参加考试。即便如此，人们还是会发现，上班变得很困难。不过到目前为止，公众已通过给报社写信，表达了对学生们的感谢。只有一两个人提出异议，说这些学生会把车开得太快！"}],"reviewStatus":"self-reviewed","translationNotes":["原英文标题 On strike. 的末尾句点在来源中标有标点或墨迹疑点；译文按“罢工”的正文内容理解，保留英文标题不作修改。"]},{"lessonId":"nce-b2-eef57c-l085","book":2,"number":85,"title":"Never too old to learn","paragraphs":[{"index":0,"enSha256":"d92bc32133017ad50a2f31bd1906a05f16161915ba9a78b02f1d4e6e733587b0","zh":"我刚收到母校的一封信，通知我以前的校长斯图尔特·佩奇先生将于下周退休。学校的新老学生将送给他一份礼物，纪念这个时刻。所有捐钱购买礼物的人，都会在一本大纪念册上签名，纪念册将送到校长家中。我们都会记得佩奇先生的耐心和体谅，也会记得，当我们很不情愿地去上学时，他曾给予我们的亲切鼓励。下星期四，许多毕业生将出席为他举行的告别晚宴。说来也巧，到了退休前一天，佩奇先生的教学生涯将正好满四十年。退休以后，他会专心从事园艺。这对他来说将是一项全新的爱好。但这没有关系，因为正如他常说的，活到老，学到老。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l086","book":2,"number":86,"title":"Out of control","paragraphs":[{"index":0,"enSha256":"169fbd2b42222eeeb7ce162a0916f51080feeba8cf7e2dc95d7d2965b83c0762","zh":"那个人正想让快艇掉头时，方向盘竟在他手里脱落了。他拼命向同伴挥手示意，那位同伴此前已经连续滑水十五分钟了。两人还没来得及弄清发生了什么，就被猛地甩进了海里。快艇撞上了一个浮标，却仍在水面上飞速前进。两人刚开始朝岸边游，就惊恐地发现，快艇正在绕圈行驶。它此刻正以惊人的速度朝他们直冲过来。不到一分钟，快艇便从离他们只有几英尺远的地方轰鸣着掠过。它驶过之后，两人尽全力继续游，因为他们知道，快艇很快又会回来。他们刚来得及游出危险区域，快艇就又绕完了一圈。不过这一次，它的速度已慢了许多，汽油几乎耗尽了。不久，发动机的声音完全消失，快艇开始在水面上缓缓漂流。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l087","book":2,"number":87,"title":"A perfect alibi","paragraphs":[{"index":0,"enSha256":"d90c6f64bc9e78d1d6ed4e9cc42783414f43c2bff87f2e176bf1aaae720d1719","zh":"“发生谋杀案的时候，我正在乘坐八点开往伦敦的那班火车。”那人说。"},{"index":1,"enSha256":"f8f0a3f43100f28ffb39e77dea625eed5a1b77bf318a2fbc41d2af2c8e32ddb7","zh":"“你总是乘这么早的火车吗？”探长问。"},{"index":2,"enSha256":"22a184cd0330b3d455233efbfeaf57a7b8aed0b1bc40ecadaf0e6b09dbe22ee7","zh":"“当然，”那人回答，“我必须在十点钟上班。我的雇主可以证明，我那天准时到了。”"},{"index":3,"enSha256":"45354d2bd7458466971bcb7d7cdd2834060b4e7d84b1a3b08f87c1d083e431ad","zh":"“如果乘晚一班的火车，你还能准时上班吗？”探长问。"},{"index":4,"enSha256":"536a608e6c71b8542e640a6e53f018658070f2256c94be3d8c2384edf558379a","zh":"“我想可以，不过我从来不乘晚一班的。”"},{"index":5,"enSha256":"1f369dd7b99ac4c28cc00be96f3542117228ee30f071be2156847060e3cec379","zh":"“你几点到的车站？”"},{"index":6,"enSha256":"8342a95e239748d519f2bed2fadbf89c2025f1b25a9bdca5fe4880ac3eaae8ea","zh":"“七点五十分。我买了份报纸，等着火车来。”"},{"index":7,"enSha256":"eae45dd30db80e010326d7f145648f3ed9308dd3bcb3ef062673406db31e09fe","zh":"“你没有注意到什么异常吗？”"},{"index":8,"enSha256":"63fc5e0a1af48ecc52cf86b35148c17afe8d64a285a8a4074a2c6aeac7e7bc3b","zh":"“当然没有。”"},{"index":9,"enSha256":"70461c2d5bd7927efde8f7e6921b9e188bf4b93ba4fc3a16200be108edfb5060","zh":"“我认为，”探长说，“你没有说实话。我认为，你乘的不是八点那班火车，而是八点二十五分那班，那班车照样能让你准时上班。你知道，谋杀案发生的那天早晨，八点那班火车根本没有开。它在芬格林站出了故障，被撤下停运了。”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l088","book":2,"number":88,"title":"Trapped in a mine","paragraphs":[{"index":0,"enSha256":"9f33ce09a2fb2d67b430e423e87e15e2126f77a103e9960cb5e303b7c6709246","zh":"六个人已经被困在矿井里十七个小时了。如果不能很快把他们救到地面，他们可能会丧命。然而，救援工作困难重重。如果使用炸药，震动就会使矿井顶部坍塌。因此，救援人员正在矿井北侧钻一个洞，打算用一只特制救生舱把他们提上来。如果泥土下面没有一层坚硬的岩石，救援人员本来几个小时就能完工。实际情况却是，他们已经钻了十六个小时，仍有很长一段距离需要打通。与此同时，两小时前放入矿井的一个麦克风，让被困者能够与最亲近的家人保持联系。尽管食物和饮水快要用完，他们仍然情绪乐观，坚信自己很快就能脱困。有人告诉他们，救援工作进展顺利。如果他们知道钻透坚硬的岩石有多困难，就会失去信心。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l089","book":2,"number":89,"title":"A slip of the tongue","paragraphs":[{"index":0,"enSha256":"72892136c27853da255faf7470523e5d92cd053980e58db6ba6e96721c77f832","zh":"为了看一场免费演出，人们什么都愿意做，哪怕演出很差也无所谓。消息传来，说P和U鸟食公司要在我们当地的电影院举办一场喜剧演出，大家便都赶去观看。我们排了好几个小时的队才能进去，演出开始前，现场想必已有几百人。不幸的是，这是我们看过的最乏味的演出之一。没能进去的人本来不必感到失望，因为许多本该出场的艺人都没有来。那天晚上，我们听到的唯一好笑的内容，来自节目开始时的广告报幕员。他显然十分紧张，在麦克风前局促地站了几分钟。他刚一开口，所有人就哄堂大笑。我们都知道这个可怜的人本来应该说什么，可他实际上说的却是：“这里是普和伊籽鸟公司。好女士们，晚上和先生们！”"}],"reviewStatus":"self-reviewed","translationNotes":["末句故意说错公司名、词序和问候语；正文保留错序笑点。正常内容本应为 P. and U. Bird Seed Company 与 Good evening, ladies and gentlemen；误说原文为 Poo and Ee Seed Bird Company 与 Good ladies, evening and gentlemen。"]},{"lessonId":"nce-b2-eef57c-l090","book":2,"number":90,"title":"What's for supper?","paragraphs":[{"index":0,"enSha256":"90620268aa4cf60307241ac6c316834a11d35b5239e070437e52ffc51f3d4586","zh":"炸鱼配薯条一直是英国人喜爱的一道菜。不过，由于海洋遭到过度捕捞，鱼变得越来越贵。因此，听说巨鱼正让北海石油钻井平台的潜水员惊恐不已，确实令人吃惊。钻井平台需要经常维修，而潜水员往往得在水下一百英尺深的黑暗中工作。他们工作时，巨鱼会撞到他们身上，把他们吓得魂不附体。现在，他们已经请人特制了一些笼子，用来保护自己免受这些巨物侵扰。这些鱼并不是鲨鱼或虎鲸，而是人们喜欢食用的鳕鱼、鳐鱼等品种。它们长到了异乎寻常的大小，有时长达十二英尺。三个因素使这些鱼长得如此巨大：海底热输油管道周围温暖的海水；钻井平台工作人员扔下海的大量食物；以及平台周围完全没有渔船。结果，这些鱼就在舒适温暖的水里，吃了又吃，长了又长。究竟是谁吃谁呢？"}],"reviewStatus":"self-reviewed","translationNotes":["末句英文为 Who cats who?；根据全文鱼、人互食的反问语境，将明显印误 cats 按 eats 的意图译为“究竟是谁吃谁呢”，未改动英文。"]},{"lessonId":"nce-b2-eef57c-l091","book":2,"number":91,"title":"Three men in a basket","paragraphs":[{"index":0,"enSha256":"29dcdf0ceb48d78093c6befc479a0b04104cebeb9cc970bd7944af299f45d043","zh":"一名飞行员发现了一个气球，它似乎正朝附近的皇家空军基地飞去。他立即通知了基地，可那里没有人能够解释这是怎么回事。控制塔上的军官听到消息后十分生气，因为气球可能给飞机带来很大危险。他说，可能有人正在侦察基地，于是飞行员接到命令，跟踪这个奇怪的物体。飞行员设法围绕气球盘旋了一阵子。他能看清气球下面的吊篮里有三个人，其中一人拿着双筒望远镜。气球飞到基地上空时，飞行员看见其中一人在拍照。没过多久，气球开始下降，落在一处机场附近。警察被叫来了，却不能逮捕任何人，因为吊篮里坐着的是两名议员和这座基地的指挥官！正如指挥官后来解释的，基地一半的人不知道另一半的人在做什么！"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l092","book":2,"number":92,"title":"Asking for trouble","paragraphs":[{"index":0,"enSha256":"9b45f4510bd51977cbbe764c62d8a552c7b0b6dcbb2e927bdcd66e7c0297f4c1","zh":"我回到家时，想必已经是凌晨两点左右。我按门铃，想叫醒妻子，可她睡得很熟。于是，我从花园的棚子里拿来一架梯子，靠在墙上，开始往卧室窗户爬。我差不多爬到窗口时，下面传来一个讥讽的声音：“我想，不用在半夜这个时候擦窗户吧。”我往下一看，发现是个警察，差点从梯子上掉下来。可我却回答道：“我就喜欢晚上擦窗户。”话一出口，我就后悔了。"},{"index":1,"enSha256":"6a04535005bd2d4654447ac76e0b0e6e5b4d5cb242a64a2a09214b79728abe4e","zh":"“我也一样。”警察用同样的口气回答，“请原谅我打断你。我不愿意打扰忙着干活的人，不过，你介意跟我到警察局走一趟吗？”"},{"index":2,"enSha256":"6092defaab83356e9832dfde2c278c31ce6e0c23cada0cb224bdcfbcc165d7d3","zh":"“嗯，我还是愿意留在这里，”我说，“你看，我忘带钥匙了。”"},{"index":3,"enSha256":"3bba97e17b259bc0a48a94cc56753e652543d1a12b74da94e850762c33056420","zh":"“你的什么？”他大声问。"},{"index":4,"enSha256":"dcf8e5900dec704dfe2ebe22b391fa0a75ecd9e094d727bb9d47d5626946613d","zh":"“我的钥匙！”我喊道。"},{"index":5,"enSha256":"ab5d6bb3e2dcb7c8df034163ba16909e37b6c51d379cf7a9a85ccb55ac4dec7c","zh":"幸好，喊声把妻子吵醒了。警察刚开始朝我爬上来，她就打开了窗户。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l093","book":2,"number":93,"title":"A noble gift","paragraphs":[{"index":0,"enSha256":"de7da10bd2cb110a3c775cab9a3eb624984104cfe2ede112f05bae084113d445","zh":"自由女神像是世界上最著名的纪念性建筑之一，是法国人民在十九世纪赠送给美国的。这座宏伟的雕像由雕塑家奥古斯特·巴托尔迪设计，历时十年才完成。雕像本体用铜制成，由一副金属框架支撑，框架是埃菲尔专门建造的。在把它运往美国之前，必须先选好地点，建起基座。最终选定的地点是纽约港入口处的一个小岛。到1884年，一座高一百五十一英尺的雕像已经在巴黎竖起。第二年，人们把它拆开，运往美国。到1886年10月底，雕像已重新组装完毕，由巴托尔迪正式赠送给美国人民。从那以后，对于经过纽约港、前往美国安家落户的数百万人来说，这座伟大的纪念像一直是自由的象征。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l094","book":2,"number":94,"title":"Future champions","paragraphs":[{"index":0,"enSha256":"98d939d7a3aada3ca94ec76b5c49ab450a68ae08a9bc773e9d29e15d5397de6d","zh":"实验证明，孩子很小的时候就能接受游泳训练。在洛杉矶一座专门的游泳池里，有些孩子还不会走路，就已经很擅长在水下屏气。两个月大的婴儿似乎并不抗拒下水。没过多久，他们就熟悉了游泳，甚至能从池底拾起重物。这些小小游泳者很喜欢的一种游戏，是水下三轮车比赛。三轮车在水面下七英尺深的池底排成一行，孩子们互相比赛，看谁先到达游泳池的另一端。不少孩子踩着踏板前进，不过大多数更愿意推着或拖着车走。有些孩子能够游完整个泳池，连一次都不用浮上水面换气。他们将来是否真能成为奥运会冠军，只有时间才能回答。不过在此之前，他们应该能鼓励我们当中那些还游不到五码，就已经上气不接下气的人。"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l095","book":2,"number":95,"title":"A fantasy","paragraphs":[{"index":0,"enSha256":"4619a280e446a3cfdc7cc9fe3b24827d52be14677964def1493b91b4f4ad726a","zh":"艾斯卡洛比亚的大使回家吃午饭时，他的妻子吓了一跳。他脸色苍白，衣服也糟糕得不像样。"},{"index":1,"enSha256":"f418dc62bd03705fc772597bdd88702e168ddd69c3e08b977b2cca62bdd9b5d4","zh":"“出了什么事？”她问，“你的衣服怎么弄得这么乱？”"},{"index":2,"enSha256":"d2a98763aca3040f34607dc036185a014750b1a8c9b4ac4357aa6a5bb003e12f","zh":"“是灭火器弄的，亲爱的，”大使淡淡地回答，“今天早晨，大学生们把大使馆点着了。”"},{"index":3,"enSha256":"f3599ba1c21913f5b0f89f37c9ba4faf21e1a5af99badfb7d6e0c5e4df27ac2c","zh":"“天哪！”妻子惊叫道，“那时你在哪儿？”"},{"index":4,"enSha256":"7cb99b3e1729c887f781e23424c7e37cb3e186bbba8af2fd9391b97349960a6a","zh":"“我像往常一样待在办公室里，”大使回答，“地下室起了火，我当然立刻下楼去了。可霍斯特那个笨蛋，竟把灭火器对准了我。他以为我身上着火了。我一定得把那家伙调走。”"},{"index":5,"enSha256":"8871a6e39ea5f13995ff014508627cf66fcc4cf4e1494595b96b2725ed7004bb","zh":"大使夫人还在接着提问，忽然发现丈夫的帽子上有个大洞。"},{"index":6,"enSha256":"60ede6955767c9febc0fca731a4ceee5e777a8e66bbbfd1417240d49678e15c3","zh":"“那这个你怎么解释？”她问。"},{"index":7,"enSha256":"1d6d4702201b666063658d55dab123034f2c3a2aced619380cf737b052894d4f","zh":"“哦，那个呀，”大使说，“有人朝我的办公室开了一枪，子弹穿过了窗户。打得挺准，你说是不是？幸好，那时我没戴帽子。要是戴着，我就没法回家吃午饭了。”"}],"reviewStatus":"self-reviewed"},{"lessonId":"nce-b2-eef57c-l096","book":2,"number":96,"title":"The dead return","paragraphs":[{"index":0,"enSha256":"703cc6da9cf812116c6cbf5ed78e3e2ee482b961fd1dbcd860234e2f6defd0e6","zh":"日本每年举行一次祭亡节。这个节日气氛欢快，因为据说在这一天，亡者会回到家中，受到生者的欢迎。人们认为，他们经过长途跋涉后会感到饥饿，因此为他们摆好食物。每家屋外都挂起特制的灯笼，帮助亡者认路。人们通宵载歌载舞。到了清晨，先前为亡者摆好的食物会被扔进河里或海里，因为活人吃这些食物被认为不吉利。在靠海的城镇，节日结束时，人们会把前一夜挂在街上的小灯笼放进水中。成千上万盏灯笼缓缓漂向大海，指引亡者踏上返回另一个世界的路程。岸边站着成群的人，目送灯笼渐渐漂远，直到再也看不见。这是一个感人的景象。"}],"reviewStatus":"self-reviewed"}]};
window.BOOK2_TRANSLATION_STATUS={"book":2,"total":96,"label":"自编中文译文（非教材官方译文）","translatedLessons":96,"translatedParagraphs":170,"reviewedLessons":96,"needsReview":[],"missingLessons":[]};
(function(){const data=window.BOOK2_TRANSLATIONS;const expected={"1":["Last week I went to the theatre. I had a very good seat. The play was very interesting. I did not enjoy it. A young man and a young woman were sitting behind me. They were talking loudly. I got very angry. I could not hear the actors. I turned round. I looked at the man and the woman angrily. They did not pay any attention. In the end, I could not bear it. I turned round again. ‘I can’t hear a word!’ I said angrily.","‘It’s none of your business,’ the young man said rudely. ‘This is a private conversation!’"],"2":["It was Sunday. I never get up early on Sundays. I sometimes stay in bed until lunchtime. Last Sunday I got up very late. I looked out of the window. It was dark outside. ‘What a day!’ I thought. ‘It’s raining again.’ Just then, the telephone rang. It was my aunt Lucy. ‘I’ve just arrived by train,’ she said. ‘I'm coming to see you.’","‘But I'm still having breakfast,’ I said.","‘What are you doing?’ she asked.","‘I'm having breakfast,’ I repeated.","‘Dear me,’ she said. ‘Do you always get up so late? It’s one o’clock!’"],"3":["Postcards always spoil my holidays. Last summer, I went to Italy. I visited museums and sat in public gardens. A friendly waiter taught me a few words of Italian. Then he lent me a book. I read a few lines, but I did not understand a word. Every day I thought about postcards. My holidays passed quickly, but I did not send cards to my friends. On the last day I made a big decision. I got up early and bought thirty-seven cards. I spent the whole day in my room, but I did not write a single card!"],"4":["I have just received a letter from my brother, Tim. He is in Australia. He has been there for six months. Tim is an engineer. He is working for a big firm and he has already visited a great number of different places in Australia. He has just bought an Australian car and has gone to Alice Springs, a small town in the centre of Australia. He will soon visit Darwin. From there, he will fly to Perth. My brother has never been abroad before, so he is finding this trip very exciting."],"5":["Mr. James Scott has a garage in Silbury and now he has just bought another garage in Pinhurst. Pinhurst is only five miles from Silbury, but Mr. Scott cannot get a telephone for his new garage, so he has just bought twelve pigeons. Yesterday, a pigeon carried the first message from Pinhurst to Silbury. The bird covered the distance in three minutes. Up to now, Mr. Scott has sent a great many requests for spare parts and other urgent messages from one garage to the other. In this way, he has begun his own private ‘telephone’ service."],"6":["I have just moved to a house in Bridge Street. Yesterday a beggar knocked at my door. He asked me for a meal and a glass of beer. In return for this, the beggar stood on his head and sang songs. I gave him a meal. He ate the food and drank the beer. Then he put a piece of cheese in his pocket and went away. Later a neighbour told me about him. Everybody knows him. His name is Percy Buttons. He calls at every house in the street once a month and always asks for a meal and a glass of beer."],"7":["The plane was late and detectives were waiting at the airport all morning. They were expecting a valuable parcel of diamonds from South Africa. A few hours earlier, someone had told the police that thieves would try to steal the diamonds. When the plane arrived, some of the detectives were waiting inside the main building while others were waiting on the airfield. Two men took the parcel off the plane and carried it into the Customs House. While two detectives were keeping guard at the door, two others opened the parcel. To their surprise, the precious parcel was full of stones and sand!"],"8":["Joe Sanders has the most beautiful garden in our town. Nearly everybody enters for ‘The Nicest Garden Competition’ each year, but Joe wins every time. Bill Frith’s garden is larger than Joe's. Bill works harder than Joe and grows more flowers and vegetables, but Joe’s garden is more interesting. He has made neat paths and has built a wooden bridge over a pool. I like gardens too, but I do not like hard work. Every year I enter for the garden competition too, and I always win a little prize for the worst garden in the town!"],"9":["On Wednesday evening, we went to the Town Hall. It was the last day of the year and a large crowd of people had gathered under the Town Hall clock. It would strike twelve in twenty minutes’ time. Fifteen minutes passed and then, at five to twelve, the clock stopped. The big minute hand did not move. We waited and waited, but nothing happened. Suddenly someone shouted, ‘It’s two minutes past twelve! The clock has stopped!’ I looked at my watch. It was true. The big clock refused to welcome the New Year. At that moment, everybody began to laugh and sing."],"10":["We have an old musical instrument. It is called a clavichord. It was made in Germany in 1681. Our clavichord is kept in the living room. It has belonged to our family for a long time. The instrument was bought by my grandfather many years ago. Recently it was damaged by a visitor. She tried to play jazz on it! She struck the keys too hard and two of the strings were broken. My father was shocked. Now we are not allowed to touch it. It is being repaired by a friend of my father’s."],"11":["I was having dinner at a restaurant when Tony Steele came in. Tony worked in a lawyer's office years ago, but he is now working at a bank. He gets a good salary, but he always borrows money from his friends and never pays it back. Tony saw me and came and sat at the same table. He has never borrowed money from me. While he was eating, I asked him to lend me twenty pounds. To my surprise, he gave me the money immediately. ‘I have never borrowed any money from you,’ Tony said, ‘so now you can pay for my dinner!’"],"12":["Our neighbour, Captain Charles Alison, will sail from Portsmouth tomorrow. We'll meet him at the harbour early in the morning. He will be in his small boat, Topsail. Topsail is a famous little boat. It has sailed across the Atlantic many times. Captain Alison will set out at eight o'clock, so we'll have plenty of time. We'll see his boat and then we'll say goodbye to him. He will be away for two months. We are very proud of him. He will take part in an important race across the Atlantic."],"13":["The Greenwood Boys are a group of pop singers. At present, they are visiting all parts of the country. They will be arriving here tomorrow. They will be coming by train and most of the young people in the town will be meeting them at the station. Tomorrow evening they will be singing at the Workers’ Club. The Greenwood Boys will be staying for five days. During this time, they will give five performances. As usual, the police will have a difficult time. They will be trying to keep order. It is always the same on these occasions."],"14":["I had an amusing experience last year. After I had left a small village in the south of France, I drove on to the next town. On the way, a young man waved to me. I stopped and he asked me for a lift. As soon as he had got into the car, I said good morning to him in French and he replied in the same language. Apart from a few words, I do not know any French at all. Neither of us spoke during the journey. I had nearly reached the town, when the young man suddenly said, very slowly, ‘Do you speak English?’ As I soon learnt, he was English himself!"],"15":["The secretary told me that Mr. Harmsworth would see me. I felt very nervous when I went into his office. He did not look up from his desk when I entered. After I had sat down, he said that business was very bad. He told me that the firm could not afford to pay such large salaries. Twenty people had already left. I knew that my turn had come.","‘Mr. Harmsworth,’ I said in a weak voice.","‘Don’t interrupt,’ he said.","Then he smiled and told me I would receive an extra thousand pounds a year!"],"16":["If you park your car in the wrong place, a traffic policeman will soon find it. You will be very lucky if he lets you go without a ticket. However, this does not always happen. Traffic police are sometimes very polite. During a holiday in Sweden, I found this. note on my car: ‘Sir, we welcome you to our city. This is a “No Parking” area. You will enjoy your stay here if you pay attention to our street signs. This note is only a reminder.’ If you receive a request like this, you cannot fail to obey it!"],"17":["My aunt Jennifer is an actress. She must be at least thirty-five years old. In spite of this, she often appears on the stage as a young girl. Jennifer will have to take part in a new play soon. This time, she will be a girl of seventeen. In the play, she must appear in a bright red dress and long black stockings. Last year in another play, she had to wear short socks and a bright, orange-coloured dress. If anyone ever asks her how old she is, she always answers, ‘Darling, it must be terrible to be grown up!’"],"18":["After I had had lunch at a village pub, I looked for my bag. I had left it on a chair beside the door and now it wasn’t there! As I was looking for it, the landlord came in.","‘Did you have a good meal?’ he asked.","‘Yes, thank you,’ I answered, ‘but I can’t pay the bill. I haven’t got my bag.’","The landlord smiled and immediately went out. In a few minutes he returned with my bag and gave it back to me.","‘I'm very sorry,’ he said. ‘My dog had taken it into the garden. He often does this!’"],"19":["‘The play may begin at any moment,’ I said. ‘It may have begun already,’ Susan answered. I hurried to the ticket office. ‘May I have two tickets please?’ I asked. ‘I'm sorry, we’ve sold out,’ the girl said. ‘What a pity!’ Susan exclaimed. Just then, a man hurried to the ticket office. ‘Can I return these two tickets?’ he asked. ‘Certainly,’ the girl said. I went back to the ticket office at once. ‘Could I have those two tickets please?’ I asked. ‘Certainly,’ the girl said, ‘but they’re for next Wednesday's performance. Do you still want them?’ ‘I might as well have them,’ I said sadly."],"20":["Fishing is my favourite sport. I often fish for hours without catching anything. But this does not worry me. Some fishermen are unlucky. Instead of catching fish, they catch old boots and rubbish. I am even less lucky. I never catch anything — not even old boots. After having spent whole mornings on the river, I always go home with an empty bag. ‘You must give up fishing!’ my friends say. ‘It’s a waste of time.’ But they don’t realize one important thing. I'm not really interested in fishing. I am only interested in sitting in a boat and doing nothing at all!"],"21":["Aeroplanes are slowly driving me mad. I live near an airport and passing planes can be heard night and day. The airport was built years ago, but for some reason it could not be used then. Last year, however, it came into use. Over a hundred people must have been driven away from their homes by the noise. I am one of the few people left. Sometimes I think this house will be knocked down by a passing plane. I have been offered a large sum of money to go away, but I am determined to stay here. Everybody says I must be mad and they are probably right."],"22":["My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland. Last year, we were travelling across the Channel and Jane put a piece of paper with her name and address on it into a bottle. She threw the bottle into the sea. She never thought of it again, but ten months later, she received a letter from a girl in Holland. Both girls write to each other regularly now. However, they have decided to use the post office. Letters will cost a little more, but they will certainly travel faster."],"23":["I had a letter from my sister yesterday. She lives in Nigeria. In her letter, she said that she would come to England next year. If she comes, she will get a surprise. We are now living in a beautiful new house in the country. Work on it had begun before my sister left. The house was completed five months ago. In my letter, I told her that she could stay with us. The house has many large rooms and there is a lovely garden. It is a very modern house, so it looks strange to some people. It must be the only modern house in the district."],"24":["I entered the hotel manager’s office and sat down. I had just lost £50 and I felt very upset. ‘I left the money in my room,’ I said, ‘and it’s not there now.’ The manager was sympathetic, but he could do nothing. ‘Everyone's losing money these days,’ he said. He started to complain about this wicked world but was interrupted by a knock at the door. A girl came in and put an envelope on his desk. It contained £50. ‘I found this outside this gentleman’s room,’ she said. ‘Well,’ I said to the manager, ‘there is still some honesty in this world!’"],"25":["I arrived in London at last. The railway station was big, black and dark. I did not know the way to my hotel, so I asked a porter. I not only spoke English very carefully, but very clearly as well. The porter, however, could not understand me. I repeated my question several times and at last he understood. He answered me, but he spoke neither slowly nor clearly. ‘I am a foreigner,’ I said. Then he spoke slowly, but I could not understand him. My teacher never spoke English like that! The porter and I looked at each other and smiled. Then he said something and I understood it. ‘You’ll soon learn English!’ he said. I wonder. In England, each person speaks a different language. The English understand each other, but I don’t understand them! Do they speak English?"],"26":["I am an art student and I paint a lot of pictures. Many people pretend that they understand modern art. They always tell you what a picture is ‘about’. Of course, many pictures are not ‘about’ anything. They are just pretty patterns. We like them in the same way that we like pretty curtain material. I think that young children often appreciate modern pictures better than anyone else. They notice more. My sister is only seven, but she always tells me whether my pictures are good or not. She came into my room yesterday.","‘What are you doing?’ she asked.","‘I'm hanging this picture on the wall,’ I answered. ‘It’s a new one. Do you like it?’","She looked at it critically for a moment. ‘It’s all right,’ she said, ‘but isn’t it upside down?’","I looked at it again. She was right! It was!"],"27":["Late in the afternoon, the boys put up their tent in the middle of a field. As soon as this was done, they cooked a meal over an open fire. They were all hungry and the food smelled good. After a wonderful meal, they told stories and sang songs by the campfire. But some time later it began to rain. The boys felt tired so they put out the fire and crept into their tent. Their sleeping bags were warm and comfortable, so they all slept soundly. In the middle of the night, two boys woke up and began shouting. The tent was full of water! They all leapt out of their sleeping bags and hurried outside. It was raining heavily and they found that a stream had formed in the field. The stream wound its way across the field and then flowed right under their tent!"],"28":["Jasper White is one of those rare people who believes in ancient myths. He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners. When he returns home at night, he always finds that someone has parked a car outside his gate. Because of this, he has not been able to get his own car into his garage even once. Jasper has put up ‘No Parking’ signs outside his gate, but these have not had any effect. Now he has put an ugly stone head over the gate. It is one of the ugliest faces I have ever seen. I asked him what it was and he told me that it was Medusa, the Gorgon. Jasper hopes that she will turn cars and their owners to stone. But none of them has been turned to stone yet!"],"29":["Captain Ben Fawcett has bought an unusual taxi and has begun a new service. The ‘taxi’ is a small Swiss aeroplane called a ‘Pilatus Porter’. This wonderful plane can carry seven passengers. The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a ploughed field. Captain Fawcett’s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains. Since then, Captain Fawcett has flown passengers to many unusual places. Once he landed on the roof of a block of flats and on another occasion, he landed in a deserted car park. Captain Fawcett has just refused a strange request from a businessman. The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous."],"30":["The Wayle is a small river that cuts across the park near my home. I like sitting by the Wayle on fine afternoons. It was warm last Sunday, so I went and sat on the river bank as usual. Some children were playing games on the bank and there were some people rowing on the river. Suddenly, one of the children kicked a ball very hard and it went towards a passing boat. Some people on the bank called out to the man in the boat, but he did not hear them. The ball struck him so hard that he nearly fell into the water. I turned to look at the children, but there weren't any in sight: they had all run away! The man laughed when he realized what had happened. He called out to the children and threw the ball back to the bank."],"31":["Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man. Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small shop. It was his job to repair bicycles and at that time he used to work fourteen hours a day. He saved money for years and in 1958, he bought a small workshop of his own. In his twenties Frank used to make spare parts for aeroplanes. At that time he had two helpers. In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people. Frank smiled when he remembered his hard early years and the long road to success. He was still smiling when the door opened and his wife came in. She wanted him to repair their grandson’s bicycle!"],"32":["People are not so honest as they once were. The temptation to steal is greater than ever before — especially in large shops. A detective recently watched a well-dressed woman who always went into a large store on Monday mornings. One Monday, there were fewer people in the shop than usual when the woman came in, so it was easier for the detective to watch her. The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the shop and handed it to an assistant who wrapped it up for her as quickly as possible. Then the woman simply took the parcel and walked out of the shop without paying. When she was arrested, the detective found out that the shop assistant was her daughter. The girl ‘gave’ her mother a free dress once a week!"],"33":["Nearly a week passed before the girl was able to explain what had happened to her. One afternoon she set out from the coast in a small boat and was caught in a storm. Towards evening, the boat struck a rock and the girl jumped into the sea. Then she swam to the shore after spending the whole night in the water. During that time she covered a distance of eight miles. Early next morning, she saw a light ahead. She knew she was near the shore because the light was high up on the cliffs. On arriving at the shore, the girl struggled up the cliff towards the light she had seen. That was all she remembered. When she woke up a day later, she found herself in hospital."],"34":["Dan Robinson has been worried all week. Last Tuesday he received a letter from the local police. In the letter he was asked to call at the station. Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore. At the station, he was told by a smiling policeman that his bicycle had been found. Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train. Dan was most surprised when he heard the news. He was amused too, because he never expected the bicycle to be found. It was stolen twenty years ago when Dan was a boy of fifteen!"],"35":["Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it. He is finding his new work far more exciting. When he was driving along Catford Street recently, he saw two thieves rush out of a shop and run towards a waiting car. One of them was carrying a bag full of money. Roy acted quickly and drove the bus straight at the thieves. The one with the money got such a fright that he dropped the bag. As the thieves were trying to get away in their car, Roy drove his bus into the back of it. While the battered car was moving away, Roy stopped his bus and telephoned the police. The thieves’ car was badly damaged and easy to recognize. Shortly afterwards, the police stopped the car and both men were arrested."],"36":["Debbie Hart is going to swim across the English Channel tomorrow. She is going to set out from the French coast at five o'clock in the morning. Debbie is only eleven years old and she hopes to set up a new world record. She is a strong swimmer and many people feel that she is sure to succeed. Debbie's father will set out with her in a small boat. Mr. Hart has trained his daughter for years. Tomorrow he will be watching her anxiously as she swims the long distance to England. Debbie intends to take short rests every two hours. She will have something to drink but she will not eat any solid food. Most of Debbie’s school friends will be waiting for her on the English coast. Among them will be Debbie’s mother, who swam the Channel herself when she was a girl."],"37":["The Olympic Games will be held in our country in four years’ time. As a great many people will be visiting the country, the government will be building new hotels, an immense stadium, and a new Olympic-standard swimming pool. They will also be building new roads and a special railway line. The Games will be held just outside the capital and the whole area will be called ‘Olympic City’. Workers will have completed the new roads by the end of this year. By the end of next year, they will have finished work on the new stadium. The fantastic modern buildings have been designed by Kurt Gunter. Everybody will be watching anxiously as the new buildings go up. We are all very excited and are looking forward to the Olympic Games because they have never been held before in this country."],"38":["My old friend, Harrison, had lived in the Mediterranean for many years before he returned to England. He had often dreamed of retiring in England and had planned to settle down in the country. He had no sooner returned than he bought a house and went to live there. Almost immediately he began to complain about the weather, for even though it was still summer, it rained continually and it was often bitterly cold. After so many years of sunshine, Harrison got a shock. He acted as if he had never lived in England before. In the end, it was more than he could bear. He had hardly had time to settle down when he sold the house and left the country. The dream he had had for so many years ended there. Harrison had thought of everything except the weather."],"39":["While John Gilbert was in hospital, he asked his doctor to tell him whether his operation had been successful, but the doctor refused to do so. The following day, the patient asked for a bedside telephone. When he was alone, he telephoned the hospital exchange and asked for Doctor Millington. When the doctor answered the phone, Mr. Gilbert said he was inquiring about a certain patient, a Mr. John Gilbert. He asked if Mr. Gilbert's operation had been successful and the doctor told him that it had been. He then asked when Mr. Gilbert would be allowed to go home and the doctor told him that he would have to stay in hosptial for another two weeks. Then Dr. Millington asked the caller if he was a relative of the patient. ‘No,’ the patient answered, ‘I am Mr. John Gilbert.’"],"40":["Last week at a dinner party, the hostess asked me to sit next to Mrs. Rumbold. Mrs. Rumbold was a large, unsmiling lady in a tight black dress. She did not even look up when I took my seat beside her. Her eyes were fixed on her plate and in a short time, she was busy eating. I tried to make conversation.","‘A new play is coming to “The Globe” soon,’ I said. ‘Will you be seeing it?’","‘No,’ she answered.","‘Will you be spending your holidays abroad this year?’ I asked.","‘No,’ she answered.","‘Will you be staying in England?’ I asked.","‘No,’ she answered.","In despair, I asked her whether she was enjoying her dinner.","‘Young man,’ she answered, ‘if you ate more and talked less, we would both enjoy our dinner!’"],"41":["‘Do you call that a hat?’ I said to my wife.","‘You needn’t be so rude about it,’ my wife answered as she looked at herself in the mirror.","I sat down on one of those modern chairs with holes in it and waited. We had been in the hat shop for half an hour and my wife was still in front of the mirror.","‘We musn’t buy things we don’t need,’ I remarked suddenly. I regretted saying it almost at once.","‘You needn't have said that,’ my wife answered. ‘I needn’t remind you of that terrible tie you bought yesterday.’","‘I find it beautiful,’ I said. ‘A man can never have too many ties.’","‘And a woman can’t have too many hats,’ she answered.","Ten minutes later we walked out of the shop together. My wife was wearing a hat that looked like a lighthouse!"],"42":["As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest. After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him. As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets. When he began to play a tune, we had our first glimpse of the snake. It rose out of the basket and began to follow the movements of the pipe. We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs. The snake, however, continued to ‘dance’ slowly. It obviously could not tell the difference between Indian music and jazz!"],"43":["In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time. Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble. At one point, it seemed certain that their plane would crash. It could only get over the mountains if it rose to 10,000 feet. Byrd at once ordered his men to throw out two heavy food sacks. The plane was then able to rise and it cleared the mountains by 400 feet. Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight. The aircraft was able to fly over the endless white plains without difficulty."],"44":["Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men. They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag. In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees. Mrs. Sterling got so angry that she ran after them. She was soon out of breath, but she continued to run. When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them. The men got such a fright that they dropped the bag and ran away. ‘The strap needs mending,’ said Mrs. Sterling later, ‘but they did not steal anything.’"],"45":["The whole village soon learnt that a large sum of money had been lost. Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office. Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him. Three months passed, and then one morning, Sam found his wallet outside his front door. It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ‘A thief, yes, but only 50 per cent a thief!’ Two months later, some more money was sent to Sam with another note: ‘Only 25 per cent a thief now!’ In time, all Sam’s money was paid back in this way. The last note said: ‘I am 100 per cent honest now!’"],"46":["When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing. No one could account for the fact that one of the boxes was extremely heavy. It suddenly occurred to one of the workers to open up the box. He was astonished at what he found. A man was lying in the box on top of a pile of woollen goods. He was so surprised at being discovered that he did not even try to run away. After he was arrested, the man admitted hiding in the box before the plane left London. He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours. The man was ordered to pay £3,500 for the cost of the trip. The normal price of a ticket is £2,000!"],"47":["A public house which was recently bought by Mr. Ian Thompson is up for sale. Mr. Thompson is going to sell it because it is haunted. He told me that he could not go to sleep one night because he heard a strange noise coming from the bar. The next morning, he found that the doors had been blocked by chairs and the furniture had been moved. Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning. He also said that he had found five empty whisky bottles which the ghost must have drunk the night before. When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head. The villagers have told him that they will not accept the pub even if he gives it away."],"48":["Dentists always ask questions when it is impossible for you to answer. My dentist had just pulled out one of my teeth and had told me to rest for a while. I tried to say something, but my mouth was full of cotton wool. He knew I collected match boxes and asked me whether my collection was growing. He then asked me how my brother was and whether I liked my new job in London. In answer to these questions I either nodded or made strange noises. Meanwhile, my tongue was busy searching out the hole where the tooth had been. I suddenly felt very worried, but could not say anything. When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth."],"49":["Tired of sleeping on the floor, a young man in Teheran saved up for years to buy a real bed. For the first time in his life, he became the proud owner of a bed which had springs and a mattress. Because the weather was very hot, he carried the bed on to the roof of his house. He slept very well for the first two nights, but on the third night, a storm blew up. A gust of wind swept the bed off the roof and sent it crashing into the courtyard below. The young man did not wake up until the bed had struck the ground. Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress. Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again."],"50":["I love travelling in the country, but I don’t like losing my way. I went on an excursion recently, but my trip took me longer than I expected.","‘I'm going to Woodford Green,’ I said to the conductor as I got on the bus, ‘but I don’t know where it is.’","‘I'll tell you where to get off,’ answered the conductor.","I sat in the front of the bus to get a good view of the countryside. After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus.","‘You'll have to get off here,’ the conductor said. ‘This is as far as we go.’","‘Is this Woodford Green?’ I asked.","‘Oh dear,’ said the conductor suddenly. ‘I forgot to put you off.’ .","‘It doesn’t matter,’ I said. ‘I'll get off here.’","‘We're going back now,’ said the conductor.","‘Well, in that case, I prefer to stay on the bus,’ I answered."],"51":["My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet. He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden. The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and sweets. Yesterday I paid him a visit. I rang the bell and was not surprised to see that Hugh was still as fat as ever. He led me into his room and hurriedly hid a large parcel under his desk. It was obvious that he was very embarrassed. When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk. He explained that his diet was so strict that he had to reward himself occasionally. Then he showed me the contents of the parcel. It contained five large bars of chocolate and three bags of sweets!"],"52":["We have just moved into a new house and I have been working hard all morning. I have been trying to get my new room in order. This has not been easy because I own over a thousand books. To make matters worse, the room is rather small, so I have temporarily put my books on the floor. At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room. A short while ago, my sister helped me to carry one of my old bookcases up the stairs. She went into my room and got a big surprise when she saw all those books on the floor. ‘This is the prettiest carpet I have ever seen,’ she said. She gazed at it for some time then added, ‘You don’t need bookcases at all. You can sit here in your spare time and read the carpet!’"],"53":["At last firemen have put out a big forest fire in California. Since then, they have been trying to find out how the fire began. Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away. Yesterday the firemen examined the ground carefully, but were not able to find any broken glass. They were also quite sure that a cigarette end did not start the fire. This morning, however, a firemen accidentally discovered the cause. He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line. In this way, he was able to solve the mystery. The explanation was simple but very unusual. A bird had snatched up the snake from the ground and then dropped it on to the wires. The snake then wound itself round the wires. When it did so, it sent sparks down to the ground and these immediately started a fire."],"54":["After breakfast, I sent the children to school and then I went to the shops. It was still early when I returned home. The children were at school, my husband was at work and the house was quiet. So I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry. At exactly that moment, the telephone rang. Nothing could have been more annoying. I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates. It took me ten minutes to persuade her to ring back later. At last I hung up the receiver. What a mess! There was pastry on my fingers, on the telephone, and on the doorknobs. I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead. This time it was the postman and he wanted me to sign for a registered letter!"],"55":["Dreams of finding lost treasure almost came true recently. A new machine called ‘The Revealer’ has been invented and it has been used to detect gold which has been buried in the ground. The machine was used in a cave near the seashore where — it is said — pirates used to hide gold. The pirates would often bury gold in the cave and then fail to collect it. Armed with the new machine, a search party went into the cave hoping to find buried treasure. The leader of the party was examining the soil near the entrance to the cave when the machine showed that there was gold under the ground. Very excited, the party dug a hole two feet deep. They finally found a small gold coin which was almost worthless. The party then searched the whole cave thoroughly but did not find anything except an empty tin trunk. In spite of this, many people are confident that ‘The Revealer’ may reveal something of value fairly soon."],"56":["Once a year, a race is held for old cars. A lot of cars entered for this race last year and there was a great deal of excitement just before it began. One of the most handsome cars was a Rolls-Royce Silver Ghost. The most unusual car was a Benz which had only three wheels. Built in 1885, it was the oldest car taking part. After a great many loud explosions, the race began. Many of the cars broke down on the course and some drivers spent more time under their cars than in them! A few cars, however, completed the race. The winning car reached a speed of forty miles an hour — much faster than any of its rivals. It sped downhill at the end of the race and its driver had a lot of trouble trying to stop it. The race gave everyone a great deal of pleasure. It was very different from modern car races but no less exciting."],"57":["A woman in jeans stood at the window of an expensive shop. Though she hesitated for a moment, she finally went in and asked to see a dress that was in the window. The assistant who served her did not like the way she was dressed. Glancing at her scornfully, he told her that the dress was sold. The woman walked out of the shop angrily and decided to punish the assistant next day. She returned to the shop the following morning dressed in a fur coat, with a handbag in one hand and a long umbrella in the other. After seeking out the rude assistant, she asked for the same dress. Not realizing who she was, the assistant was eager to serve her this time. With great difficulty, he climbed into the shop window to get the dress. As soon as she saw it, the woman said she did not like it. She enjoyed herself making the assistant bring almost everything in the window before finally buying the dress she had first asked for."],"58":["The tiny village of Frinley is said to possess a ‘cursed tree’. Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased. The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation. It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die. Many villagers believe that the tree has already claimed a number of victims. The vicar has been asked to have the tree cut down, but so far he has refused. He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it. In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk. So far, not one of them has been struck down by sudden death!"],"59":["Our dog, Rex, used to sit outside our front gate and bark. Every time he wanted to come into the garden he would bark until someone opened the gate. As the neighbours complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in. Rex soon became an expert at opening the gate. However, when I was going out shopping last week, I noticed him in the garden near the gate. This time he was barking so that someone would let him out! Since then, he has developed another bad habit. As soon as he opens the gate from the outside, he comes into the garden and waits until the gate shuts. Then he sits and barks until someone lets him out. After this he immediately lets himself in and begins barking again. Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since."],"60":["At a village fair, I decided to visit a fortune-teller called Madam Bellinsky. I went into her tent and she told me to sit down. After I had given her some money, she looked into a crystal ball and said: ‘A relation of yours is coming to see you. She will be arriving this evening and intends to stay for a few days. The moment you leave this tent, you will get a big surprise. A woman you know well will rush towards you. She will speak to you and then she will lead you away from this place. That is all.’","As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me. ‘Where have you been hiding?’ she asked impatiently. ‘Your sister will be here in less than an hour and we must be at the station to meet her. We are late already.’ As she walked away, I followed her out of the fair."],"61":["The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars. Right from the start there was trouble with the Hubble. The pictures it sent us were very disappointing because its main mirror was faulty! NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it. The shuttle Endeavour will be taking the astronauts to the Hubble. A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs. Of course, the Hubble is above the earth’s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen. The Hubble will tell us a great deal about the age and size of the universe. By the time you read this, the Hubble's eagle eye will have sent us thousands and thousands of wonderful pictures."],"62":["Firemen had been fighting the forest fire for nearly three weeks before they could get it under control. A short time before, great trees had covered the countryside for miles around. Now, smoke still rose up from the warm ground over the desolate hills. Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well. When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly. The seed was sprayed over the ground in huge quantities by aeroplanes. The planes had been planting seed for nearly a month when it began to rain. By then, however, in many places the grass had already taken root. In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil."],"63":["Jeremy Hampden has a large circle of friends and is very popular at parties. Everybody admires him for his great sense of humour — everybody. that is, except his six-year-old daughter, Jenny. Recently, one of Jeremy's closest friends asked him to make a speech at a wedding reception. This is the sort of thing that Jeremy loves. He prepared the speech carefully and went to the wedding with Jenny. He had included a large number of funny stories in the speech and, of course, it was a great success. As soon as he had finished, Jenny told him she wanted to go home. Jeremy was a little disappointed by this but he did as his daughter asked. On the way home, he asked Jenny if she had enjoyed the speech. To his surprise, she said she hadn’t. Jeremy asked her why this was so and she told him that she did not like to see so many people laughing at him!"],"64":["In 1858, a French engineer, Aimé Thomé de Gamond, arrived in England with a plan for a twenty-one-mile tunnel under the English Channel. He said that it would be possible to build a platform in the centre of the Channel. This platform would serve as a port and a railway station. The tunnel would be well-ventilated if tall chimneys were built above sea level. In 1860, a better plan was put forward by an Englishman, William Low. He suggested that a double railway-tunnel should be built. This would solve the problem of ventilation, for if a train entered this tunnel, it would draw in fresh air behind it. Forty-two years later a tunnel was actually begun. If, at the time, the British had not feared invasion, it would have been completed. The world had to wait almost another 100 years for the Channel Tunnel. It was officially opened on March 7, 1994, finally connecting Britain to the European continent."],"65":["Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children’s hospital. Dressed up as Father Christmas and accompanied by a ‘guard of honour’ of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo. He should have known that the police would never allow this sort of thing. A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic. Though Jimmy agreed to go at once, Jumbo refused to move. Fifteen policemen had to push very hard to get him off the main street. The police had a difficult time, but they were most amused. ‘Jumbo must weigh a few tons,’ said a policeman afterwards, ‘so it was fortunate that we didn’t have to carry him. Of course, we should arrest him, but as he has a good record, we shall let him off this time.’"],"66":["In 1963 a Lancaster bomber crashed on Wallis Island, a remote place in the South Pacific, a long way west of Samoa. The plane wasn’t too badly damaged, but over the years, the crash was forgotten and the wreck remained undisturbed. Then in 1989, twenty-six years after the crash, the plane was accidentally rediscovered in an aerial survey of the island. By this time, a Lancaster bomber in reasonable condition was rare and worth rescuing. The French authorities had the plane packaged and moved in parts back to France. Now a group of enthusiasts are going to have the plane restored. It has four Rolls-Royce Merlin engines, but the group will need to have only three of them rebuilt. Imagine their surprise and delight when they broke open the packing cases and found that the fourth engine was sweet as honey — still in perfect condition. A colony of bees had turned the engine into a hive and it was totally preserved in beeswax!"],"67":["Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world. In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro. Tazieff was able to set up his camp very close to the volcano while it was erupting violently. Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long. He noticed that a river of liquid rock was coming towards him. It threatened to surround him completely, but Tazieff managed to escape just in time. He waited until the volcano became quiet and he was able to return two days later. This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures. Tazieff has often risked his life in this way. He has been able to tell us more about active volcanoes than any man alive."],"68":["I crossed the street to avoid meeting him, but he saw me and came running towards me. It was no use pretending that I had not seen him, so I waved to him. I never enjoy meeting Nigel Dykes. He never has anything to do. No matter how busy you are, he always insists on coming with you. I had to think of a way of preventing him from following me around all morning.","‘Hello, Nigel,’ I said. ‘Fancy meeting you here!’","‘Hi, Elizabeth,’ Nigel answered. ‘I was just wondering how to spend the morning — until I saw you. You're not busy doing anything, are you?’","‘No, not at all,’ I answered. ‘I'm going to ...’","‘Would you mind my coming with you?’ he asked, before I had finished speaking.","‘Not at all,’ I lied, ‘but I'm going to the dentist.’","‘Then I'll come with you,’ he answered. ‘There’s always plenty to read in the waiting room!’"],"69":["I was being tested for a driving licence for the third time. I had been asked to drive in heavy traffic and had done so successfully. After having been instructed to drive out of town, I began to acquire confidence. Sure that I had passed, I was almost beginning to enjoy my test. The examiner must have been pleased with my performance, for he smiled and said, ‘Just one more thing, Mr. Eames. Let us suppose that a child suddenly crosses the road in front of you. As soon as I tap on the window, you must stop within five feet.’ I continued driving and after some time, the examiner tapped loudly. Though the sound could be heard clearly, it took me a long time to react. I suddenly pressed the brake pedal hard and we were both thrown forward. The examiner looked at me sadly. ‘Mr. Eames,’ he said, in a mournful voice, ‘you have just killed that child!’"],"70":["During a bullfight, a drunk suddenly wandered into the middle of the ring. The crowd began to shout, but the drunk was unaware of the danger. The bull was busy with the matador at the time, but it suddenly caught sight of the drunk who was shouting rude remarks and waving a red cap. Apparently sensitive to criticism, the bull forgot all about the matador and charged at the drunk. The crowd suddenly grew quiet. The drunk, however, seemed quite sure of himself. When the bull got close to him, he clumsily stepped aside to let it pass. The crowd broke into cheers and the drunk bowed. By this time, however, three men had come into the ring and they quickly dragged the drunk to safety. Even the bull seemed to feel sorry for him, for it looked on sympathetically until the drunk was out of the way before once more turning its attention to the matador."],"71":["When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C. If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected. Big Ben takes its name from Sir Benjamin Hall who was responsible for the making of the clock when the new Houses of Parliament were being built. It is not only of immense size, but is extremely accurate as well. Officials from Greenwich Observatory have the clock checked twice a day. On the B.B.C. you can hear the clock when it is actually striking because microphones are connected to the clock tower. Big Ben has rarely gone wrong. Once, however, it failed to give the correct time. A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!"],"72":["The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour. He set up a new world record in September 1935 at Bonneville Salt Flats, Utah. Bluebird, the car he was driving, had been specially built for him. It was over 30 feet in length and had a 2,500-horsepower engine. Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tyre burst during the first run. After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour. However, a few days later, he was told that a mistake had been made. His average speed had been 301 miles per hour. Since that time, racing drivers have reached speeds over 600 miles an hour. Following in his father’s footsteps many years later, Sir Malcolm's son, Donald, also set up a world record. Like his father, he was driving a car called Bluebird."],"73":["Children who play truant from school are unimaginative. A quiet day's fishing, or eight hours in a cinema seeing the same film over and over again, is usually as far as they get. They have all been put to shame by a boy who, while playing truant, travelled 1,600 miles. He hitchhiked to Dover and, towards evening, went into a boat to find somewhere to sleep. When he woke up next morning, he discovered that the boat had, in the meantime, travelled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a lorry. The driver gave him a few biscuits and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the centre of Paris as he hoped it would, but to Perpignan on the French-Spanish border. There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school."],"74":["An ancient bus stopped by a dry river bed and a party of famous actors and actresses got off. Dressed in dark glasses and old clothes, they had taken special precautions so that no one should recognize them. But as they soon discovered, disguises can sometimes be too perfect.","‘This is a wonderful place for a picnic,’ said Gloria Gleam.","‘It couldn’t be better, Gloria,’ Brinksley Meers agreed. ‘No newspaper men, no film fans! Why don’t we come more often?’","Meanwhile, two other actors, Rockwall Slinger and Merlin Greeves, had carried two large food baskets to a shady spot under some trees. When they had all made themselves comfortable, a stranger appeared. He looked very angry. ‘Now you get out of here, all of you!’ he shouted. ‘I'm sheriff here. Do you see that notice? It says “No Camping” — in case you can’t read!’","‘Look, sheriff,’ said Rockwall, ‘don’t be too hard on us. I'm Rockwall Slinger and this is Merlin Greeves.’","‘Oh, is it?’ said the sheriff with a sneer. ‘Well, I'm Brinksley Meers, and my other name is Gloria Gleam. Now you get out of here fast!’"],"75":["When a light passenger plane flew off course some time ago, it crashed in the mountains and its pilot was killed. The only passengers, a young woman and her two baby daughters, were unhurt. It was the middle of winter. Snow lay thick on the ground. The woman knew that the nearest village was miles away. When it grew dark, she turned a suitcase into a bed and put the children inside it, covering them with all the clothes she could find. During the night, it got terribly cold. The woman kept as near as she could to the children and even tried to get into the case herself, but it was too small. Early next morning, she heard planes passing overhead and wondered how she could send a signal. Then she had an idea. She stamped out the letters ‘SOS’ in the snow. Fortunately, a pilot saw the signal and sent a message by radio to the nearest town. It was not long before a helicopter arrived on the scene to rescue the survivors of the plane crash."],"76":["‘To end our special news bulletin,’ said the voice of the television announcer, ‘we're going over to the macaroni fields of Calabria. Macaroni has been grown in this area for over six hundred years. Two of the leading growers, Giuseppe Moldova and Riccardo Brabante, tell me that they have been expecting a splendid crop this year and harvesting has begun earlier than usual. Here you can see two workers who, between them, have just finished cutting three cartloads of golden brown macaroni stalks. The whole village has been working day and night gathering and threshing this year’s crop before the September rains. On the right, you can see Mrs. Brabante herself. She has been helping her husband for thirty years now. Mrs. Brabante is talking to the manager of the local factory where the crop is processed. This last scene shows you what will happen at the end of the harvest: the famous Calabrian macaroni-eating competition! Signor Fratelli, the present champion, has won it every year since 1991. And that ends our special bulletin for today, Thursday, April 1st. We're now going back to the studio.’"],"77":["The mummy of an Egyptian woman who died in 800 B.C. has just had an operation. The mummy is that of Shepenmut who was once a singer in the Temple of Thebes. As there were strange marks on the X-ray plates taken of the mummy, doctors have been trying to find out whether the woman died of a rare disease. The only way to do this was to operate. The operation, which lasted for over four hours, proved to be very difficult because of the hard resin which covered the skin. The doctors removed a section of the mummy and sent it to a laboratory. They also found something which the X-ray plates did not show: a small wax figure of the god Duamutef. This god which has the head of a cow was normally placed inside a mummy. The doctors have not yet decided how the woman died. They feared that the mummy would fall to pieces when they cut it open, but fortunately this has not happened. The mummy successfully survived the operation."],"78":["After reading an article entitled ‘Cigarette Smoking and Your Health’ I lit a cigarette to calm my nerves. I smoked with concentration and pleasure as I was sure that this would be my last cigarette. For a whole week I did not smoke at all and during this time, my wife suffered terribly. I had all the usual symptoms of someone giving up smoking: a bad temper and an enormous appetite. My friends kept on offering me cigarettes and cigars. They made no effort to hide their amusement whenever I produced a packet of sweets from my pocket. After seven days of this I went to a party. Everybody around me was smoking and I felt extremely uncomfortable. When my old friend Brian urged me to accept a cigarette, it was more than I could bear. I took one guiltily, lit it and smoked with satisfaction. My wife was delighted that things had returned to normal once more. Anyway, as Brian pointed out, it is the easiest thing in the world to give up smoking. He himself has done it lots of times!"],"79":["I used to travel by air a great deal when I was a boy. My parents used to live in South America and I used to fly there from Europe in the holidays. A flight attendant would take charge of me and I never had an unpleasant experience. I am used to travelling by air and only on one occasion have I ever felt frightened. After taking off, we were flying low over the city and slowly gaining height, when the plane suddenly turned round and flew back to the airport. While we were waiting to land, a flight attendant told us to keep calm and to get off the plane quietly as soon as it had touched down. Everybody on board was worried and we were curious to find out what had happened. Later we learnt that there was a very important person on board. The police had been told that a bomb had been planted on the plane. After we had landed, the plane was searched thoroughly. Fortunately, nothing was found and five hours later we were able to take off again."],"80":["Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851. The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it. A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth’s steam hammer. Though in those days, travelling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train. There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936."],"81":["When he had killed the guard, the prisoner of war quickly dragged him into the bushes. Working rapidly in the darkness, he soon changed into the dead man’s clothes. Now, dressed in a blue uniform and with a rifle over his shoulder, the prisoner marched boldly up and down in front of the camp. He could hear shouting in the camp itself. Lights were blazing and men were running here and there: they had just discovered that a prisoner had escaped. At that moment, a large black car with four officers inside it, stopped at the camp gates. The officers got out and the prisoner stood to attention and saluted as they passed. When they had gone, the driver of the car came towards him. The man obviously wanted to talk. He was rather elderly with grey hair and clear blue eyes. The prisoner felt sorry for him, but there was nothing else he could do. As the man came near, the prisoner knocked him to the ground with a sharp blow. Then, jumping into the car, he drove off as quickly as he could."],"82":["Fishermen and sailors sometimes claim to have seen monsters in the sea. Though people have often laughed at stories told by seamen, it is now known that many of these ‘monsters’ which have at times been sighted are simply strange fish. Occasionally, unusual creatures are washed to the shore, but they are rarely caught out at sea. Some time ago, however, a peculiar fish was caught near Madagascar. A small fishing boat was carried miles out to sea by the powerful fish as it pulled on the line. Realizing that this was no ordinary fish, the fisherman made every effort not to damage it in any way. When it was eventually brought to shore, it was found to be over thirteen feet long. It had a head like a horse, big blue eyes, shining silver skin, and a bright red tail. The fish, which has since been sent to a museum where it is being examined by a scientist, is called an oarfish. Such creatures have rarely been seen alive by man as they live at a depth of six hundred feet."],"83":["The former Prime Minister, Mr. Wentworth Lane, was defeated in the recent elections. He is now retiring from political life and has gone abroad. My friend, Patrick, has always been a fanatical opponent of Mr. Lane's Radical Progressive Party. After the elections, Patrick went to the former Prime Minister's house. When he asked if Mr. Lane lived there, the policeman on duty told him that since his defeat, the ex-Prime Minister had gone abroad. On the following day, Patrick went to the house again. The same policeman was just walking slowly past the entrance, when Patrick asked the same question. Though a little suspicious this time, the policeman gave him the same answer. The day after, Patrick went to the house once more and asked exactly the same question. This time, the policeman lost his temper. ‘I told you yesterday and the day before yesterday,’ he shouted, ‘Mr. Lane was defeated in the elections. He has retired from political life and gone to live abroad!’","‘I know,’ answered Patrick, ‘but I love to hear you say it!’"],"84":["Busmen have decided to go on strike next week. The strike is due to begin on Tuesday. No one knows how long it will last. The busmen have stated that the strike will continue until general agreement is reached about pay and working conditions. Most people believe that the strike will last for at least a week. Many owners of private cars are going to offer ‘free rides’ to people on their way to work. This will relieve pressure on the trains to some extent. Meanwhile, a number of university students have volunteered to drive buses while the strike lasts. All the students are expert drivers, but before they drive any of the buses, they will have to pass a special test. The students are going to take the test in two days’ time. Even so, people are going to find it difficult to get to work. But so far, the public has expressed its gratitude to the students in letters to the Press. Only one or two people have objected that the students will drive too fast!"],"85":["I have just received a letter from my old school, informing me that my former headmaster, Mr. Stuart Page, will be retiring next week. Pupils of the school, old and new, will be sending him a present to mark the occasion. All those who have contributed towards the gift will sign their names in a large album which will be sent to the headmaster’s home. We shall all remember Mr. Page for his patience and understanding and for the kindly encouragement he gave us when we went so unwillingly to school. A great many former pupils will be attending a farewell dinner in his honour next Thursday. It is a curious coincidence that the day before his retirement, Mr. Page will have been teaching for a total of forty years. After he has retired, he will devote himself to gardening. For him, this will be an entirely new hobby. But this does not matter, for, as he has often remarked, one is never too old to learn."],"86":["As the man tried to swing the speedboat round, the steering wheel came away in his hands. He waved desperately to his companion, who had been water skiing for the last fifteen minutes. Both men had hardly had time to realize what was happening when they were thrown violently into the sea. The speedboat had struck a buoy, but it continued to move very quickly across the water. Both men had just begun to swim towards the shore, when they noticed with dismay that the speedboat was moving in a circle. It now came straight towards them at tremendous speed. In less than a minute, it roared past them only a few feet away. After it had passed, they swam on as quickly as they could because they knew that the boat would soon return. They had just had enough time to swim out of danger when the boat again completed a circle. On this occasion, however, it had slowed down considerably. The petrol had nearly all been used up. Before long, the noise dropped completely and the boat began to drift gently across the water."],"87":["‘At the time the murder was committed, I was travelling on the 8 o’clock train to London,’ said the man.","‘Do you always catch such an early train?’ asked the inspector.","‘Of course I do,’ answered the man. ‘I must be at work at 10 o'clock. My employer will confirm that I was there on time.’","‘Would a later train get you to work on time?’ asked the inspector.","‘I suppose it would, but I never catch a later train.’","‘At what time did you arrive at the station?’","‘At ten to eight. I bought a paper and waited for the train.’","‘And you didn’t notice anything unusual?’","‘Of course not.’","‘I suggest,’ said the inspector, ‘that you are not telling the truth. I suggest that you did not catch the 8 o'clock train, but that you caught the 8.25 which would still get you to work on time. You see, on the morning of the murder, the 8 o'clock train did not run at all. It broke down at Ferngreen station and was taken off the line.’"],"88":["Six men have been trapped in a mine for seventeen hours. If they are not brought to the surface soon they may lose their lives. However, rescue operations are proving difficult. If explosives are used, vibrations will cause the roof of the mine to collapse. Rescue workers are therefore drilling a hole on the north side of the mine. They intend to bring the men up in a special capsule. If there had not been a hard layer of rock beneath the soil, they would have completed the job in a few hours. As it is, they have been drilling for sixteen hours and they still have a long way to go. Meanwhile, a microphone, which was lowered into the mine two hours ago, has enabled the men to keep in touch with their closest relatives. Though they are running out of food and drink, the men are cheerful and confident that they will get out soon. They have been told that rescue operations are progressing smoothly. If they knew how difficult it was to drill through the hard rock, they would lose heart."],"89":["People will do anything to see a free show — even if it is a bad one. When the news got round that a comedy show would be presented at our local cinema by the P. and U. Bird Seed Company, we all rushed to see it. We had to queue for hours to get in and there must have been several hundred people present just before the show began. Unfortunately, the show was one of the dullest we have ever seen. Those who failed to get in need not have felt disappointed, as many of the artistes who should have appeared did not come. The only funny things we heard that evening came from the advertiser at the beginning of the programme. He was obviously very nervous and for some minutes stood awkwardly before the microphone. As soon as he opened his mouth, everyone burst out laughing. We all know what the poor man should have said, but what he actually said was: ‘This is the Poo and Ee Seed Bird Company. Good ladies, evening and gentlemen!’"],"90":["Fish and chips has always been a favourite dish in Britain, but as the oceans have been overfished, fish has become more and more expensive. So it comes as a surprise to learn that giant fish are terrifying the divers on North Sea oil rigs. Oil rigs have to be repaired frequently and divers, who often have to work in darkness a hundred feet under water, have been frightened out of their wits by giant fish bumping into them as they work. Now they have had special cages made to protect them from these monsters. The fish are not sharks or killer whales, but favourite eating varieties like cod and skate which grow to unnatural sizes, sometimes as much as twelve feet in length. Three factors have caused these fish to grow so large: the warm water round the hot oil pipes under the sea; the plentiful supply of food thrown overboard by the crews on the rigs; the total absence of fishing boats around the oil rigs. As a result, the fish just eat and eat and grow and grow in the lovely warm water. Who cats who?"],"91":["A pilot noticed a balloon which seemed to be making for a Royal Air Force Station nearby. He informed the station at once, but no one there was able to explain the mystery. The officer in the control tower was very angry when he heard the news, because balloons can be a great danger to aircraft. He said that someone might be spying on the station and the pilot was ordered to keep track of the strange object. The pilot managed to circle the balloon for some time. He could make out three men in a basket under it and one of them was holding a pair of binoculars. When the balloon was over the station, the pilot saw one of the men taking photographs. Soon afterwards, the balloon began to descend and it landed near an airfield. The police were called in, but they could not arrest anyone, for the basket contained two Members of Parliament and the Commanding Officer of the station! As the Commanding Officer explained later, one half of the station did not know what the other half was doing!"],"92":["It must have been about two in the morning when I returned home. I tried to wake up my wife by ringing the doorbell, but she was fast asleep, so I got a ladder from the shed in the garden, put it against the wall, and began climbing towards the bedroom window. I was almost there when a sarcastic voice below said, ‘I don’t think the windows need cleaning at this time of the night.’ I looked down and nearly fell off the ladder when I saw a policeman. I immediately regretted answering in the way I did, but I said, ‘I enjoy cleaning windows at night.’","‘So do I,’ answered the policeman in the same tone. ‘Excuse my interrupting you. I hate to interrupt a man when he’s busy working, but would you mind coming with me to the station?’","‘Well, I'd prefer to stay here,’ I said. ‘You see, I've forgotten my key.’","‘Your what?’ he called.","‘My key,’ I shouted.","Fortunately, the shouting woke up my wife who opened the window just as the policeman had started to climb towards me."],"93":["One of the most famous monuments in the world, the Statue of Liberty, was presented to the United States of America in the nineteenth century by the people of France. The great statue, which was designed by the sculptor Auguste Bartholdi, took ten years to complete. The actual figure was made of copper supported by a metal framework which had been especially constructed by Eiffel. Before it could be transported to the United States, a site had to be found for it and a pedestal had to be built. The site chosen was an island at the entrance of New York Harbour. By 1884, a statue which was 151 feet tall had been erected in Paris. The following year, it was taken to pieces and sent to America. By the end of October 1886, the statue had been put together again and it was officially presented to the American people by Bartholdi. Ever since then, the great monument has been a symbol of liberty for the millions of people who have passed through New York Harbour to make their homes in America."],"94":["Experiments have proved that children can be instructed in swimming at a very early age. At a special swimming pool in Los Angeles, children become expert at holding their breath under water even before they can walk. Babies of two months old do not appear to be reluctant to enter the water. It is not long before they are so accustomed to swimming that they can pick up weights from the floor of the pool. A game that is very popular with these young swimmers is the underwater tricycle race. Tricycles are lined up on the floor of the pool seven feet under water. The children compete against each other to reach the other end of the pool. Many pedal their tricycles, but most of them prefer to push or drag them. Some children can cover the whole length of the pool without coming up for breath even once. Whether they will ever become future Olympic champions, only time will tell. Meanwhile, they should encourage those among us who cannot swim five yards before they are gasping for air."],"95":["When the Ambassador of Escalopia returned home for lunch, his wife got a shock. He looked pale and his clothes were in a frightful state.","‘What has happened?’ she asked. ‘How did your clothes get into such a mess?’","‘A fire extinguisher, my dear,’ answered the Ambassador drily. ‘University students set the Embassy on fire this morning.’","‘Good heavens!’ exclaimed his wife. ‘And where were you at the time?’","‘I was in my office as usual,’ answered the Ambassador. ‘The fire broke out in the basement. I went down immediately, of course, and that fool, Horst, aimed a fire extinguisher at me. He thought I was on fire. I must definitely get that fellow posted.’","The Ambassador's wife went on asking questions, when she suddenly noticed a big hole in her husband's hat.","‘And how can you explain that?’ she asked.","‘Oh, that,’ said the Ambassador. ‘Someone fired a shot through my office window. Accurate, don’t you think? Fortunately, I wasn’t wearing it at the time. If I had been, I would not have been able to get home for lunch.’"],"96":["A Festival for the Dead is held once a year in Japan. This festival is a cheerful occasion, for on this day, the dead are said to return to their homes and they are welcomed by the living. As they are expected to be hungry after their long journey, food is laid out for them. Specially-made lanterns are hung outside each house to help the dead to find their way. All night long, people dance and sing. In the early morning, the food that had been laid out for the dead is thrown into a river or into the sea as it is considered unlucky for anyone living to eat it. In towns that are near the sea, the tiny lanterns which had been hung in the streets the night before, are placed into the water when the festival is over. Thousands of lanterns slowly drift out to sea guiding the dead on their return journey to the other world. This is a moving spectacle, for crowds of people stand on the shore watching the lanterns drifting away until they can be seen no more."]};const planned=data.lessons.map(t=>{const l=window.LESSONS.find(x=>x.book===2&&x.number===t.number);if(!l||l.id!==t.lessonId||!l.textbook||l.textbook.title!==t.title||l.paragraphs.length!==t.paragraphs.length||t.paragraphs.some(p=>l.paragraphs[p.index].en!==expected[t.number][p.index]))throw Error('Book 2 translation source mismatch: '+t.number);return {l,t};});for(const {l,t} of planned){for(const p of t.paragraphs)l.paragraphs[p.index].zh=p.zh;l.translation={label:data.label,reviewStatus:t.reviewStatus,notes:t.translationNotes||[]};l.textbook.translation=l.translation;}})();
